import { ChangeDetectorRef, Component, EventEmitter, Input, Output, SimpleChanges } from '@angular/core';
import { FactHeaderComponent } from '../fact-header/fact-header.component';
import { hightlightModeType } from '../../../../rt/interfaces/feed.interface';
import { IssueListComponent } from "../../../../rt/components/issues/issue-list/issue-list.component";
import { HeaderType, selectedIssues } from '../../../../rt/interfaces/issue.interface';
import { MatCheckboxChange, MatCheckboxModule } from '@angular/material/checkbox';
import { MatFormFieldModule } from '@angular/material/form-field';
import { FormBuilder, FormGroup, FormsModule, Validators } from '@angular/forms';
import { MatInputModule } from '@angular/material/input';
import { ButtonComponent } from "../../../../shared/components/button/button.component";
import { FullFactComponent } from '../full-fact/full-fact.component';
import { factAssigneeType, factCreationMdl, selectedContactList, selectedTaskItem } from '../../../interfaces/fact.interface';
import { TostbarService } from '../../../../core/services/tost/tostbar.service';
import { DocInfo, FACTFROM, globAnnot, highlightToolType } from '../../../../pdf/interfaces/pdf.interface';
import { CommonService } from '../../../../shared/services/common/common.service';
import { FactNoteComponent } from "../../../../pdf/components/facts/fact-note/fact-note.component";
import { myTeamUsers } from '../../../interfaces/teamshare.interface';
import { factdata } from '../../../../shared/interfaces/fact.interface';
import { AnnotsService } from '../../../../rt/services/annots/annots.service';
import { IssueService } from '../../../../rt/services/issue/issue.service';
import { annotTypes, factAnnotCordinates, feedAnnotations, feedAnnotCordinates } from '../../../../rt/interfaces/annotation.interface';
import { RtFactService } from '../../../../shared/services/rt-fact/rt-fact.service';
import { jDateType } from '../date-form/date-form.component';
import { FeedDisplayService } from '../../../../rt/services/feed-display/feed-display.service';
import { linkType } from '../../../../shared/interfaces/common.interface';
import { FactService } from '../../../../shared/services/fact/fact.service';
import { FadeScrollDirective } from '../../../../shared/directive/fade-scroll.directive';
import { BroadcastingService } from '../../../../core/services/broadcasting/broadcasting.service';
import { SelectionActionsService } from '../../../../shared/services/selection-actions/selection-actions.service';
import { BROADCAST_EVENTS } from '../../../../userpanel/utility/user-panel-constants';
import { NgScrollbarModule } from 'ngx-scrollbar';

@Component({
  selector: 'fact-creation',
  standalone: true,
  imports: [FactHeaderComponent, IssueListComponent, MatCheckboxModule, MatFormFieldModule, FormsModule,
     MatInputModule, ButtonComponent, FullFactComponent, FactNoteComponent, FadeScrollDirective, NgScrollbarModule],
  templateUrl: './fact-creation.component.html',
  styleUrl: './fact-creation.component.scss'
})
export class FactCreationComponent {
  @Input() cFFrom: FACTFROM = 'RT';
  @Input() isCompoent: boolean = false;
  @Output() OutEvent = new EventEmitter<any>();

  @Input() headerType: HeaderType;
  @Input() nSesid: string;
  @Input() nBundledetailid: string;

  @Input() nEditIssueid: string;
  @Output() nEditIssueidChange: EventEmitter<string> = new EventEmitter<string>();


  @Input() nUserid: string;
  @Input() nCaseid: string;

  @Input() hightlightMode: hightlightModeType;
  @Input() hightlightModeChange: EventEmitter<hightlightModeType>;


  @Input() visibleIssueModel: boolean;
  @Input() visibleIssueModelChange: EventEmitter<boolean>;
  @Input() annotGlobMode: globAnnot = 'S';
  @Input() selectedlinktype: linkType = {} as linkType;


  showError: boolean = false;
  selectedIssues: selectedIssues[] = [];

  selectedContacts: selectedContactList[] = []

  selectedTasks: selectedTaskItem[] = [];

  cPermission: 'N' | 'E' = 'N'

  currentStep: number = 1;

  issueFormDilog: any;

  isNote: boolean = true;
  cNote: string;

  assignMode: factAssigneeType;

  isSubmitted: boolean = false

  @Input() jFiles: DocInfo[] = [];

  frm: FormGroup;

  @Input() userList: myTeamUsers[] = [];

  jTexts: string[] = [''];

  isEmpty: boolean = true;

  haschange: boolean = false;

  isNoteEdited: boolean = false;

  @Input() nEditFactid: string;
  @Output() nEditFactidChange: EventEmitter<string> = new EventEmitter<string>();

  quickFactDetail: factdata;
  jDate: jDateType;

  bUseHighlightedText: boolean = false;

  isValidated: boolean = false
  isHaveTempAnnot: boolean = false;

  @Input() annotToolMode: highlightToolType;
  jOTexts: string[] = [];
  constructor(private tost: TostbarService, private common: CommonService, private fb: FormBuilder, private rtfactService: RtFactService,
    private annotsService: AnnotsService, private fds: FeedDisplayService, private cdr: ChangeDetectorRef, private factService: FactService,
    private broadCastService: BroadcastingService,
    private selectionActionsService: SelectionActionsService,
    private issueService: IssueService
  ) { }

  async ngOnInit() {
    if (this.nEditFactid) {
      this.cPermission = 'E';
      this.getFactDetailById();
    }

    // Pre-populate selectedIssues from the QFact panel's effective selection
    // when creating a new QFact (not editing). This ensures the right-side
    // "Choose Claim & Issue" checkboxes match whatever the user picked in
    // the LEFT QFact panel (or the default Unassigned issue).
    if (this.hightlightMode === 'QF' && this.cPermission === 'N') {
      const effectiveIds = this.selectionActionsService.qfactSelected();
      if (effectiveIds.length) {
        // User explicitly selected issues in the QFact panel — use them.
        this.selectedIssues = effectiveIds.map((nIid, i) => ({
          nIid,
          nImpactid: 0,
          nRelid: 0,
          dt: new Date().toISOString(),
          serialno: i,
        }));
      } else {
        // No explicit picks — replicate the QFact panel's fallback to the
        // system Unassigned issue. Fetch the issue list to find its nIid.
        try {
          const res = await this.issueService.fetchIssueListV2({
            nCaseid: this.nCaseid,
            nSessionid: null,
            nIDid: null,
            nUserid: this.nUserid,
          });
          const issues: any[] = res?.[1] ?? [];
          const unassigned = issues.find(i => i.cIName === 'Unassigned');
          if (unassigned) {
            // Carry cIName through so onSelectedIssuesChange can recognise
            // and drop this implicit fallback once the user picks a real
            // issue. Without it the filter has nothing to match against.
            this.selectedIssues = [{
              nIid: unassigned.nIid,
              nImpactid: 0,
              nRelid: 0,
              dt: new Date().toISOString(),
              serialno: 0,
              cIName: unassigned.cIName,
            } as any];
          }
        } catch { /* non-fatal — issue-list will still load its own list */ }
      }
    }

    this.buildForm();
    this.userList = await this.common.getMyTeamUsers(this.nCaseid);
    if (this.userList?.length) {
      this.userList = this.userList.filter(x => x.nUserid != this.nUserid);
      // if (this.cPermission != 'E') {
      this.userList = this.userList.map(x => {
        if (x.isAdmin) {
          x.isSelected = true;
          x.bCanEdit = true;
          x.bCanCopy = true;
          x.bCanReshare = true;
          x.bCanComment = true;
        }
        return x;
      });
      // }
    }
    this.isHaveTempAnnot = this.annotsService.isHaveTempAnnot();

    // QFact "Include selected text + note" sub-option: pre-tick the
    // "Use highlighted text in note" checkbox and seed the note textarea
    // with the highlighted text, so the user lands in the panel with the
    // selection already copied across — they only need to add commentary
    // around it. Same trigger as fillhilighttext({checked:true}) but
    // executed on panel open instead of waiting for a manual tick.
    if (
      this.hightlightMode === 'QF' &&
      this.cPermission === 'N' &&
      this.selectionActionsService.state().qfIncludeTextPlusNote &&
      this.isHaveTempAnnot
    ) {
      const tempAnnots = this.annotsService.getTemp();
      if (tempAnnots.length) {
        const fullText = tempAnnots[0].fullText || '';
        if (fullText) {
          this.bUseHighlightedText = true;
          this.jTexts = [fullText];
          this.jOTexts = [...this.jTexts];
          this.isEmpty = false;
        }
      }
    }
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['visibleIssueModel']) {

    }
  }

  buildForm() {
    this.frm = this.fb.group({
      nFiletype: [0, Validators.required],
      nStatus: [0, Validators.required],
    })

  }


  fillhilighttext(ev: MatCheckboxChange) {
    if (ev.checked) {
      const tempAnnots = this.annotsService.getTemp();
      if (tempAnnots.length) {
        const fullText = tempAnnots[0].fullText || '';
        this.jTexts = [fullText];
        this.jOTexts = [...this.jTexts];
        this.isEmpty = false;
      }
    }
    else {
      this.jTexts = [''];
      this.isEmpty = true;
    }
  }

  submitForm() {

    if (this.hightlightMode == 'QF') {
      this.qFactSubmit();
      // submit apis 
    }
    else if (this.hightlightMode == 'F') {
      if (this.currentStep == 1) {
        this.currentStep = 2;
      }
      else {
        this.factSubmit();
      }
    }
  }


  convToStr(val: any) {
    return JSON.stringify(val);
  }

  choosenfiles() {
    return this.jFiles.map((a) => ([a.nBundledetailid, a.jLinktype, ((a.highlights && a.highlights.length) ? a.highlights : []), (a.texts ? a.texts : [])]))
  }

  choosenUsers() {
    return this.userList.filter(f => f.isSelected).map(m => ({
      nUserid: m.nUserid,
      bCanEdit: m.bCanEdit,
      bCanCopy: m.bCanCopy,
      bCanReshare: m.bCanReshare,
      bCanComment: m.bCanComment
    }));
  }

  async factSubmit() {
    debugger;





    try {

      if (!this.selectedIssues.length || (!this.validateJDate() && this.hightlightMode == 'F' && this.currentStep == 2)) {
        this.showError = true;
        this.cdr.detectChanges();
        return;
      }


      if (!this.selectedIssues.length) {
        this.tost.error('Please select atleast one issue');
        return;
      }

      if (!this.validateJDate()) {
        this.tost.error('Please select a valid date');
        return;
      }


      if (this.isSubmitted) {
        return;
      }
      this.isValidated = true;
      this.isSubmitted = true;
      const { msg, data: jCordinates, nPage, nLine } = this.annotGlobMode != 'M' ? this.getJCordinates(this.cFFrom) : { msg: 1, data: [], nPage: null, nLine: null };
      if (msg == -1) {
        return;
      }


      const colorid = await this.lastID();

      let finalMDL: factCreationMdl = {
        nColorid: colorid,
        nFt: this.frm.value.nFiletype,
        nSt: this.frm.value.nStatus,
        // jT: this.convToStr(this.jTexts.filter(a => a)),
        jT: this.convToStr(this.jTexts.filter(a => typeof a === 'string' && a.trim() !== '')),
        jOT: this.convToStr(this.getJOText()),
        jFl: this.convToStr(this.choosenfiles()),
        jIssues: this.convToStr(this.selectedIssues.map(a => ([a.nIid, (a.nImpactid ? a.nImpactid : 0), (a.nRelid ? a.nRelid : 0)]))),
        jContacts: this.convToStr(this.selectedContacts.map(a => a.nContactid)),
        jTasks: this.convToStr(this.selectedTasks.map(a => a.nTaskid)),
        jUsers: this.convToStr(this.choosenUsers()),
        cFtype: 'F',
        cFFrom: this.cFFrom,
        nPage,
        nLine,
        nCaseid: this.nCaseid,
        jDate: this.convToStr(this.jDate),
        bIsHighlighted: this.bUseHighlightedText
      }



      if (this.cFFrom == 'RT') {
        finalMDL.nSesid = this.nSesid;
        finalMDL.jCordinates = jCordinates;
      } else {
        finalMDL.nBDid = this.nBundledetailid;
        finalMDL.jAn = this.convToStr(jCordinates);
        finalMDL.cType = this.annotGlobMode;
        finalMDL.jLinktype = this.convToStr(this.selectedlinktype);
      }

      if (this.quickFactDetail) {
        finalMDL.nQFSid = this.quickFactDetail.nFSid;
        // finalMDL.jCordinates = jCordinates;
      }
      const res = await this.rtfactService.saveFact(finalMDL);

      this.isSubmitted = false;

      if (res["msg"] == 1) {
        this.updateAnnots(res.nFSid, res.color, this.hightlightMode, jCordinates, nPage, nLine);
        this.tost.openSnackBar(res["value"]);
        this.fds.emit('FACT-ADDED', { nFSid: res["nFSid"], color: res["color"], nQFSid: this.quickFactDetail ? this.quickFactDetail.nFSid : 0, annot: { jCordinates, id: res.nFSid, color: res.color, cType: this.hightlightMode, nPage, nLine } });
        // Send reload event
        this.sendReloadEvent('fact-created', { nFSid: res["nFSid"] });
        this.closeFactCreation();
      } else {
        this.tost.error('Fact creation failed');
      }
    } catch (error: any) {
      this.tost.error(error.message);
      this.isSubmitted = false;
    }

  }

  async lastID(): Promise<number> {
    // Highlight colour follows the LAST issue the user clicked — same spec
    // and same logic as rtFactService.lastID(). Keeping the two in sync
    // ensures a QFact's colour is preserved when it's converted to a full
    // Fact: the QFact stored its colour from selectedIssues[length-1], the
    // Fact must source it from the same position. The previous getcolorid
    // round-trip returned the server-ranked first row instead, which is why
    // converting a multi-issue QFact came out a different colour.
    if (!this.selectedIssues?.length) return 0;
    this.selectedIssues.map(a => a.nIid = a.nIid || a.nIssueid);
    const lastId: any = this.selectedIssues[this.selectedIssues.length - 1]?.nIid;
    return lastId || 0;
  }

  async qFactSubmit() {
    try {
      debugger;
      if (!this.selectedIssues.length) return;

      if (this.isSubmitted) {
        return;
      }
      this.isSubmitted = true;

      const { msg, data: jCordinates, nPage, nLine } = this.getJCordinates(this.cFFrom);
      if (msg == -1) {
        return;
      }

      const jContacts = this.convToStr([...new Set(this.selectedContacts.map(a => a.nContactid))]);
      if (this.cPermission == 'N') {
        // const { res } = await this.factService.submitQuickFactV2(this.selectedIssues, this.docInfo, this.jTexts, this.tempAnnots, this.isNoteEdited, jLinktype, jContacts);

        const jOT = this.convToStr(this.getJOText());
        const jLinktype = this.convToStr(this.selectedlinktype) || '{}';
        debugger;
        const jUsers = this.convToStr(this.choosenUsers());
        const { res } = await this.rtfactService.submitQuickFact(this.nSesid, this.nBundledetailid, this.selectedIssues, this.nCaseid, this.jTexts, jCordinates, this.isNoteEdited, jContacts, nPage, nLine, this.cFFrom, jOT, jLinktype, this.bUseHighlightedText, jUsers);
        this.isSubmitted = false;
        if (res["msg"] == 1) {
          this.updateAnnots(res.nFSid, res.color, this.hightlightMode, jCordinates, nPage, nLine);
          this.tost.openSnackBar(res["value"]);
          this.fds.emit('QUICK-FACT-ADDED', { nFSid: res["nFSid"], color: res["color"], annot: { jCordinates, id: res.nFSid, color: res.color, cType: this.hightlightMode, nPage, nLine } });
          // Send reload event
          this.sendReloadEvent('quick-fact-created', { nFSid: res["nFSid"] });
          this.closeFactCreation();
        } else {
          this.tost.error('Q fact creation failed');
        }
      }
      else {

        const colorid = await this.lastID();

        const mdl = {
          nFSid: this.quickFactDetail.nFSid,
          nColorid: colorid,
          // jTexts: this.convToStr(this.jTexts.filter(a => a)),
          jTexts: this.convToStr(this.jTexts.filter(a => typeof a === 'string' && a.trim() !== '')),
          jIssue: this.convToStr(this.selectedIssues.map(a => ([a.nIssueid || a.nIid, a.nImpactid || 0, (a.nRelid || a.nRelevanceid) || 0]))),
          cIsNote: 'N', //this.isNoteEdited ? 'N' : 'N'
          jContacts,
          nPage,
          nLine
        };
        const res = await this.rtfactService.updateQuickFact(mdl);
        this.isSubmitted = false;
        if (res.msg == 1) {
          this.updateAnnots(res.nFSid, res.color, this.hightlightMode, jCordinates, nPage, nLine);

          this.fds.emit('QUICK-FACT-UPDATED', { nFSid: res["nFSid"], color: res["color"] });
          this.tost.openSnackBar(res["value"]);
          this.closeFactCreation();

          // Send reload event
          this.sendReloadEvent('quick-fact-updated', { nFSid: res["nFSid"] });
        } else {
          this.tost.error(res.value);
        }
      }
    } catch (error: any) {
      this.tost.error(error.message);
      this.isSubmitted = false;
    }

  }

  closeFactCreation() {
    if (this.nEditFactid) {
      this.nEditFactid = null;
      this.nEditFactidChange.emit(this.nEditFactid);
    }
    this.hightlightMode = null;
    this.hightlightModeChange.emit(this.hightlightMode);
  }

  textchange(ev) {
    this.haschange = true;
  }

  emitFactNote(event) {
    if (event.event == 'ADD-CONTECT') {
      this.selectedContacts.push(event.data.original)
    }
  }

  async getFactDetailById() {
    const res = await this.rtfactService.getFactDetailById(this.nEditFactid);
    if (res.length) {
      if (res[0][0]) {
        this.quickFactDetail = res[0][0];
      }
      this.selectedIssues = res[1] || [];
      this.selectedContacts = res[2] || [];

      // A Full Fact must never carry the Unassigned placeholder — it's a
      // QFact-only marker for "captured but not yet categorised". When this
      // panel initialises in Fact mode (e.g. converting a QFact whose only
      // issue was Unassigned, or editing a legacy Fact that still has it),
      // strip Unassigned out so the picker accurately reflects the saved
      // state and the Next button's [disabled]="!selectedIssues?.length"
      // gate fires correctly. Without this strip, an orphan Unassigned in
      // selectedIssues keeps the button enabled while the picker (which
      // hides Unassigned in Fact mode) shows nothing ticked.
      //
      // selectedIssues from res[1] doesn't always carry cIName, so cross-
      // check against quickFactDetail.issueList (factIssues — has cIName)
      // and exclude any matching nIid/nIssueid as well.
      if (this.hightlightMode === 'F') {
        const unassignedIds = new Set<string>(
          (this.quickFactDetail?.issueList || [])
            .filter(i => i?.cIName === 'Unassigned')
            .flatMap(i => [i?.nIid, i?.nIssueid].filter((x): x is string => !!x))
        );
        this.selectedIssues = this.selectedIssues.filter((i: any) =>
          i?.cIName !== 'Unassigned' &&
          !unassignedIds.has(i?.nIid) &&
          !unassignedIds.has(i?.nIssueid)
        );
      }

      if (this.quickFactDetail) {
        // jTexts is typed string[] but the backend has historically returned
        // some entries as non-string payloads (notably for QFacts saved via
        // older flows). Coerce anything non-string to '' so the downstream
        // .trim() filter in factSubmit / qFactSubmit doesn't blow up on
        // conversion ("a.trim is not a function").
        const jTexts = this.quickFactDetail?.jTexts?.map(a => (typeof a === 'string' ? a : '')) || [];
        this.jTexts = [...jTexts];

        if (this.jTexts?.length) {
          this.bUseHighlightedText = true;
        }

        if (!this.jTexts.length) {
          this.jTexts.push('');
        }
      }
      this.cdr.detectChanges();
    }
    if (this.cFFrom == 'I') {
      const annot: any = await this.rtfactService.getFactAnnotations(this.nEditFactid);
      if (annot && annot.length) {
        this.annotsService.set(annot[0]);
        this.isHaveTempAnnot = this.annotsService.isHaveTempAnnot();
        this.cdr.detectChanges();
      }
    }
  }

  updateAnnots(nFSid: string, color: string, cType: annotTypes, jCordinates: feedAnnotCordinates[], nPage: number, nLine: number) {
    const updateAnnot = { jCordinates, id: nFSid, color: color, cType: cType, nPage, nLine };
    this.annotsService.set(updateAnnot);
    this.annotsService.removeTemp();
  }

  getJCordinates(cFFrom: any) {
    debugger;
    try {
      const annotation: feedAnnotations[] = this.annotsService.getTemp() || [];

      if (!annotation.length && this.cPermission == 'N') {
        this.tost.error('Please mark the annotation first');
        return { msg: -1, data: [] };
      }

      const firstAnnot = annotation[0] || null;
      let jCordinates: any;
      if (cFFrom == 'RT') {
        const jCordinat: feedAnnotCordinates[] = this.cPermission === 'N' ? firstAnnot?.jCordinates || [] : this.quickFactDetail?.jCordinates || [];
        jCordinates = jCordinat;
      } else {
        const factCordinate: factAnnotCordinates = { uuid: firstAnnot?.['uuid'], type: firstAnnot?.['type'], page: firstAnnot?.['page'], rects: firstAnnot?.['rects'], lines: firstAnnot?.['lines'], width: firstAnnot?.['width'] };

        const jFactCordinat: any[] = this.cPermission === 'N' ? firstAnnot ? [factCordinate] : [] : this.quickFactDetail?.jCordinates || [factCordinate] || [];
        jCordinates = jFactCordinat;
      }

      const nPage = this.cPermission === 'N' ? firstAnnot?.nPage || firstAnnot?.['page'] || 0 : this.quickFactDetail?.nPage || firstAnnot?.['page'] || 0;
      const nLine = this.cPermission === 'N' ? firstAnnot?.nLine || 0 : this.quickFactDetail?.nLine || 0;
      return { msg: 1, data: jCordinates, nLine, nPage };

    } catch (error) {
      return { msg: -1, data: [], nLine: 0, nPage: 0 };
    }

  }



  validateJDate() {
    if (!this.jDate) {
      return false
    }
    if (!this.jDate.record || this.jDate.record.length === 0) {
      return false;
    } else if (this.jDate.type == 'D' && this.jDate.record[0].date == null) {
      return false;
    } else if (this.jDate.type == 'MY' && (this.jDate.record[0].month == null || this.jDate.record[0].year == null)) {
      return false;
    } else if (this.jDate.type == 'Y' && this.jDate.record[0].year == null) {
      return false;
    }

    return true;
  }


  getJOText(): string[] {
    const tempAnnots = this.annotsService.getTemp();
    if (tempAnnots.length) {
      const fullText = tempAnnots[0].fullText || '';
      return [fullText];
    }
    return [];
  }

  issuesLength: number = 0;


  issuesLengthChange(event: number) {
    this.issuesLength = event;
  }

  /** Mirror right-panel checkbox toggles back into the LEFT QFact panel.
   *  ngOnInit seeds selectedIssues from SelectionActionsService.qfactSelected()
   *  (LEFT → RIGHT). This handler closes the loop the other way: when the user
   *  ticks/unticks an issue in the "Choose Claim & Issue" list the shared
   *  signal updates so the LEFT panel chips re-render in sync.
   *
   *  Only mirror in QFact creation mode — Fact mode and edit (cPermission='E')
   *  shouldn't clobber the user's standing QFact picks. */
  onSelectedIssuesChange(updated: selectedIssues[]) {
    // Defensive — Unassigned shouldn't reach here because the picker hides
    // it in Fact mode, but if anything ever pushes it through (e.g. a
    // future bidirectional sync from a QFact-side toggle), drop it before
    // it lands in the Fact's selectedIssues.
    if (this.hightlightMode === 'F') {
      updated = (updated || []).filter(i => i?.cIName !== 'Unassigned');
    } else if (this.hightlightMode === 'QF') {
      // QFact mode: Unassigned is the implicit fallback that ngOnInit pre-ticks
      // when the user hasn't picked anything yet. The moment any real issue is
      // selected the fallback should drop, otherwise the saved QFact gets
      // tagged with both Unassigned + the real picks. Mirrors the LEFT panel's
      // effectiveSelection semantics (explicit picks beat Unassigned).
      const list = updated || [];
      const hasReal = list.some(i => i?.cIName !== 'Unassigned');
      if (hasReal) {
        updated = list.filter(i => i?.cIName !== 'Unassigned');
      }
    }
    this.selectedIssues = updated;
    if (this.hightlightMode === 'QF' && this.cPermission === 'N') {
      this.selectionActionsService.setQFactIssues((updated || []).map(i => i.nIid));
    }
  }

  // Add this method
  private sendReloadEvent(action: string, data: any) {
    console.log('Sending reload event:', { action, data, nCaseid: this.nCaseid });
    this.broadCastService.portMessage({
      event: BROADCAST_EVENTS.RELOAD_FILE_LIST,
      data: {
        nCaseid: this.nCaseid,
        action: action,
        ...data,
        timestamp: Date.now(),
        tabId: this.broadCastService.tabId
      }
    });
  }

}
