import { Component, EventEmitter, Input, Output } from '@angular/core';
import moment from 'moment'; // Correct default import
import { interval, Subscription } from 'rxjs';

@Component({
  selector: 'counter',
  standalone: true,
  imports: [],
  templateUrl: './counter.component.html',
  styleUrl: './counter.component.scss'
})
export class CounterComponent {


  @Input() time: string; // input start time
  @Input() todate: string; // input start time

  @Input() countDown: number = 60;
  remaining: number = this.countDown; // countdown in seconds
  private sub!: Subscription;


  @Input() isEditable: boolean;
  @Output() isEditableChange = new EventEmitter<boolean>();

  ngOnInit() {
    const start = moment(this.time); // given start time
    const now = moment(this.todate);
    
    const elapsed = now.diff(start, 'seconds');

    // Adjust remaining time (60 - elapsed seconds)
    this.remaining = Math.max(60 - elapsed, 0);

    if (0 >= this.remaining) {
      this.isEditable = false;
      this.isEditableChange.emit(this.isEditable);
    }

    // Start ticking every 1s
    this.sub = interval(1000).subscribe(() => {
      if (this.remaining > 0) {
        this.remaining--;
      } else {
        this.sub.unsubscribe();
        this.isEditable = false;
        this.isEditableChange.emit(this.isEditable);
      }
    });
  }

  ngOnDestroy() {
    if (this.sub) {
      this.sub.unsubscribe();
      this.isEditable = false;
      this.isEditableChange.emit(this.isEditable);
    }
  }



}
