import { Component, EventEmitter, Input, Output } from '@angular/core';
import { IconComponent } from '../../../../shared/components/icon/icon.component';
import { ButtonComponent } from '../../../../shared/components/button/button.component';
import { hightlightModeType } from '../../../../rt/interfaces/feed.interface';
import { MatMenuModule } from '@angular/material/menu';
import { AnnotsService } from '../../../../rt/services/annots/annots.service';
import { FeedDisplayService } from '../../../../rt/services/feed-display/feed-display.service';

@Component({
  selector: 'fact-header',
  standalone: true,
  imports: [IconComponent, ButtonComponent, MatMenuModule],
  templateUrl: './fact-header.component.html',
  styleUrl: './fact-header.component.scss'
})
export class FactHeaderComponent {

  @Input() hightlightMode: hightlightModeType;
  @Input() hightlightModeChange: EventEmitter<hightlightModeType>;

  @Input() visibleIssueModelChange: EventEmitter<boolean>;

  @Input() currentStep: number;
  @Output() currentStepChange: EventEmitter<number> = new EventEmitter<number>();


  @Input() issuesLength: number;

  constructor(private annotsService: AnnotsService,private fds: FeedDisplayService,) { }

  close() {
    this.annotsService.disableAnnotBox();
    this.annotsService.removeTemp();
    this.hightlightMode = null;
    this.hightlightModeChange.emit(this.hightlightMode);
    this.fds.emit('CLOSE', {});
  }

  openIssueManager() {
    this.visibleIssueModelChange.emit(true);
  }

  back() {
    this.currentStep = 1;
    this.currentStepChange.emit(this.currentStep);

  }
}
