import { Component, DestroyRef, EventEmitter, inject, Input, Output, SimpleChanges } from '@angular/core';
import { NavQfactcardComponent } from "../nav-qfactcard/nav-qfactcard.component";
import { MarknavService } from '../../../../services/marknav/marknav.service';
import { IssueDetail, LinkDetail, markNavEvents, navigateModeType, navigateSubList, viewModeType } from '../../../../interfaces/marknav.interface';
import { Subject, Subscription } from 'rxjs';
import { finalFilterList } from '../../../../../shared/interfaces/filter.interface';
import { FactcardComponent } from "../../../../../pdf/components/linkviews/facts/factcard/factcard.component";
import { FactService } from '../../../../../shared/services/fact/fact.service';
import { AnnotsService } from '../../../../services/annots/annots.service';
import { feedAnnotCordinates, qMarksAnnots } from '../../../../interfaces/annotation.interface';
import { linkLines, SessionEvent } from '../../../../interfaces/feed-display.interface';
import { FeedDisplayService } from '../../../../services/feed-display/feed-display.service';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { SecureStorageService } from '../../../../../core/services/storage/secure-storage.service';
import { IconComponent } from "../../../../../shared/components/icon/icon.component";
import { NavDocLinkCardComponent } from "../nav-doc-link-card/nav-doc-link-card.component";
import { MatMenuModule } from '@angular/material/menu';
import { RtDocsService } from '../../../../../shared/services/rt-docs/rt-docs.service';
import { ButtonComponent } from "../../../../../shared/components/button/button.component";
import { factdata } from '../../../../../shared/interfaces/fact.interface';
import { annotDetails } from '../../../../interfaces/feed.interface';
import { FACTFROM } from '../../../../../pdf/interfaces/pdf.interface';
import { historyBuilderMdl, markNavjFilters } from '../../../../../shared/interfaces/mark-nav-filter.interface';
import { docItem } from '../../../../../shared/interfaces/doc.interface';
import { TostbarService } from '../../../../../core/services/tost/tostbar.service';
import { BroadcastingService } from '../../../../../core/services/broadcasting/broadcasting.service';
import { broadCastBody } from '../../../../../core/interfaces/login.interface';

import { CommonModule } from '@angular/common';
import { TranslateModule } from '@ngx-translate/core';

@Component({
  selector: 'navall',
  standalone: true,
  imports: [CommonModule, TranslateModule, NavQfactcardComponent, FactcardComponent, IconComponent, NavDocLinkCardComponent, MatMenuModule, ButtonComponent],
  templateUrl: './navall.component.html',
  styleUrl: './navall.component.scss'
})
export class NavallComponent {
  @Input() cFFrom: FACTFROM = 'RT';
  @Input() nBundledetailid: string;
  @Input() nSesid: string;
  @Input() nUserid: string;
  @Input() sortBy: string = 'desc';

  @Input() activeID: string;
  @Output() OnEvent: EventEmitter<any> = new EventEmitter();

  @Input() selectedIds: string[];
  @Output() selectedIdsChange: EventEmitter<string[]> = new EventEmitter<string[]>();

  @Input() selectedMode: navigateModeType;
  @Input() viewmode: viewModeType;

  @Input() noOfRecord: number;
  @Output() noOfRecordChange: EventEmitter<number> = new EventEmitter<number>();
  list: any[] = []

  // @Input() linkLines: linkLines[];
  // @Input() linkLinesChange: EventEmitter<linkLines[]>;

  @Input() currentPage: number;

  private destroyRef = inject(DestroyRef);

  private endListenerdestroyed$ = new Subject<void>();

  @Input() visibleAnnotDetails: annotDetails
  @Input() visibleAnnotDetailsChange: EventEmitter<annotDetails>;


  @Input() jFilters: markNavjFilters;

  @Input() historyEnabled: boolean;

  @Input() nFSid: string;
  type: string;

  @Input() bIsTranscipt: boolean;

  factSheetDeleteSubscription: Subscription;

  @Input() bisHistorExists: boolean;
  @Output() bisHistorExistsChange: EventEmitter<boolean> = new EventEmitter<boolean>();
  @Output() isAllQf: EventEmitter<boolean> = new EventEmitter<boolean>();

  constructor(
    private markNavService: MarknavService,
    private factService: FactService,
    private annotsService: AnnotsService,
    private fds: FeedDisplayService,
    private store: SecureStorageService,
    private rtDoc: RtDocsService,
    private tost: TostbarService,
    private broadCastService: BroadcastingService
  ) {
    this.factSheetDeleteSubscription = this.broadCastService.factSheetDeleteListener().subscribe((body: broadCastBody) => {
      this.handleFactSheetDelete(body?.data);
    });
  }

  ngOnInit() {
    this.initList();
    this.handleFeedEvent();
  }

  ngOnChanges(changes: SimpleChanges): void {

    if (changes['jFilters'] && !changes['jFilters'].firstChange) {
      this.initList();
    }

    if (changes && changes['sortBy'] && !changes['sortBy'].firstChange) {
      this.initList();
    }

    if (changes['currentPage'] && !changes['currentPage'].firstChange) {
      if (this.visibleAnnotDetails?.source == 'ICON') {
        this.scrollToPage()
      }
    }

    if (changes["visibleAnnotDetails"]) {
      if (this.visibleAnnotDetails?.id && this.visibleAnnotDetails?.source == 'ICON') {
        this.scrollToId(this.visibleAnnotDetails?.id);
      }
    }

    if (changes["historyEnabled"] && !changes["historyEnabled"].firstChange) {
      this.initList();
    }


    if (changes["nFSid"]) {
      if (changes["nFSid"].currentValue == null) {
        this.nFSid = null;
      }
    }
  }

  ngOnDestroy(): void {
    try {
      this.endListenerdestroyed$.next();
      this.endListenerdestroyed$.complete();
    } catch (error) {
    }
    try {
      if (this.factSheetDeleteSubscription) {
        this.factSheetDeleteSubscription.unsubscribe();
      }
    } catch (error) {
    }
  }

  async initList() {
    try {
      const res: any = await this.markNavService.getAll(this.nSesid, this.nUserid, 'H', this.sortBy, 1, this.jFilters, this.nBundledetailid, this.historyEnabled, this.bIsTranscipt);
      const templist = res?.[0] || [];
      this.list = []

      if (templist.length) {
        const issueDetails: IssueDetail[] = res[1] || [];
        const linkDetails: LinkDetail[] = res[2] || [];

        templist.forEach((e) => {
          e.cPageno = e.nPage;
          if (e.cSource === 'F' || e.cSource === 'FL' || e.cSource === 'QF') {
            e.issueList = issueDetails.filter(x => x.jFSids.includes(e.nFSid));
            e.linkfile = linkDetails.filter(x => x.nFSid === e.nFSid);
            this.list.push(e);
          }
          else {
            this.list.push(e);
          }
        });
      }


      this.noOfRecord = templist.length;
      this.noOfRecordChange.emit(this.noOfRecord);

      if (this.visibleAnnotDetails?.id) {
        this.scrollToId(this.visibleAnnotDetails?.id)
      }

      if (this.list?.length) {
        for (let x of ['QF', 'QM', 'F', 'D']) {
          this.handleSequence(this.list, x);
        }
      }
      // setTimeout(() => {
      //   this.scrollToActiveFact();
      // }, 100);
      let isAllQF = this.list.every(item => item.cSource === "QF");

      if (isAllQF) {
        this.isAllQf.emit(true);
      } else {
        this.isAllQf.emit(false);
      }
      this.selectedIds = this.list.map(i => i.id);
      this.selectedIdsChange.emit(this.selectedIds);
    } catch (error) {
      console.error('Error initializing list:', error);
    } finally {
    }
  }


  qFactCardEvent(e: markNavEvents) {
    if (e.event == 'DELETE-FACT') {
      if (!e.data?.nFSid) return;
      this.deleteqfact(e.data?.nFSid);
      this.fds.emit('DELETE-ANNOTATION', { type: 'DELETE-ANNOTATION', id: e.data?.nFSid });
    }
    else if (['CONVERT-TO-FACT', 'EDIT-Q-FACT'].includes(e.event)) {
      this.annotsService.delete(e.data?.nFSid);
      this.fds.emit('CLOSE', { type: 'ANNOT-DETAILS', modeltype: e.event == 'EDIT-Q-FACT' ? 'QF' : 'F' });
      this.OnEvent.emit(e);
    }
  }


  // async factCardEvent(e: any, x: factdata) {
  //   if (e.event == 'VIEW') {
  //     e.x = x;
  //     this.OnEvent.emit(e);
  //   }
  // }
  async factCardEvent(e: any, x: factdata) {
    if (this.type == e.data && this.nFSid == x.nFSid) {
      this.nFSid = null;
      this.type = '';
    } else {
      this.nFSid = x.nFSid;
      this.type = e.data;
    }
    if (e.event == 'VIEW') {
      e.x = x;
      this.OnEvent.emit(e);
    }
  }


  async docCardEvent(e: markNavEvents, x: docItem) {
    this.nFSid = x.nFSid;
    this.type = e.type;
    if (e.event == 'DOC-CARD-VIEW') {
      e.data = x;
      this.OnEvent.emit(e);
    } if (e.event == 'OPEN-COMPARE-MODE') {
      this.fds.emit(e.event, { ...e.data });
    }
  }

  async deleteqfact(nFSid: string) {
    const res = await this.factService.deleteFact(nFSid);
    if (res && res.msg == 1) {
      this.annotsService.delete(nFSid);
      this.list = this.list.filter(x => x.nFSid != nFSid);
      this.noOfRecord = this.list.length;
      this.noOfRecordChange.emit(this.noOfRecord);
    }
  }

  scrollToActiveFact() {

    if (!this.activeID) return;

    const activeElement = document.getElementById(`fact-${this.activeID}`);

    if (activeElement) {
      activeElement.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }
  }



  scrollToPage() {
    try {
      document.querySelector(`[nav-all] [data-page="${this.currentPage}"]`)?.scrollIntoView();
    } catch (error) {
      console.error(error)
    }
  }

  scrollToId(id: string) {
    try {
      setTimeout(() => {
        document.querySelector(`[nav-all] [id="${id}"]`)?.scrollIntoView();
      }, 200);

    } catch (error) {
      console.error(error)
    }
  }


  scrollFeedToPage(x: any) {
    if (x?.nPage) {
      this.fds.emit('SCROLL-TO-PAGE', { page: x.nPage || 1, id: x.id, line: x.nLine || 12 });
    } else if (x?.jLinktype?.pages) {
      this.fds.emit('SCROLL-TO-PAGE', { page: x?.jLinktype?.pages[0], id: x.id });
    } else if (x?.jLinktype?.start) {
      this.fds.emit('SCROLL-TO-PAGE', { page: x?.jLinktype?.start, id: x.id });
    } else {
      this.fds.emit('SCROLL-TO-PAGE', { page: 1, id: x.id });
    }
  }

  handleSequence(list: any[], type: string) {
    let nSequence = 0;
    let nCurrentPage = 0;
    for (const item of list) {
      if (item.cSource != type) continue;
      nSequence++;
      if ((item.nPage != nCurrentPage)) {
        nSequence = 1;
        nCurrentPage = item.nPage;
      }
      // Show the real line number whenever the SP returned one. Works for:
      //   - QM (highlights) via RHighlights.cTLineno (already populated by
      //     the highlights branch in run3.py)
      //   - F / QF (facts) and D (doc-links) via FactDetail.nTLine /
      //     DocDetail.nTLine — populated by the new dual-write in
      //     assets/pythons/annot-transfer/run3.py and surfaced by
      //     et_navigate_get_all's CASE on bIsTranscipt.
      // Falls back to the per-page sequence counter only when nLine is
      // null/0 (orphaned annotations on the published view, or rows that
      // genuinely have no anchor line).
      item.nSequence = item.nLine ? item.nLine : nSequence;
    }
  }



  private async addQMarkToList(qMark: qMarksAnnots) {

    const userInfo = await this.store.getUserInfo();

    const newItem = {
      cSource: 'QM', // Quick Mark
      cPageno: qMark.cPageno,
      nPage: qMark.cPageno,
      nLine: qMark.cLineno,
      dCreateDt: new Date().toISOString(),
      id: qMark.nHid,
      cCreateby: userInfo.cFname + ' ' + (userInfo.cLname || ''),
      cTime: qMark.cTime,
    };

    this.list.unshift(newItem);

    this.handleSequence(this.list, 'QM');

    this.noOfRecord++;
    this.noOfRecordChange.emit(this.noOfRecord);
  }

  private removeQMarkFromList(nHid: string) {
    const index = this.list.findIndex(item => item.id === nHid);
    if (index !== -1) {
      this.list.splice(index, 1);

      this.noOfRecord--;
      this.noOfRecordChange.emit(this.noOfRecord);

      this.handleSequence(this.list, 'QM');
    }
  }

  async deleteDocLink(nDocid: string) {
    try {
      const res = await this.rtDoc.deleteDoc(nDocid);
      if (res.msg == 1) {
        this.annotsService.delete(nDocid);
        this.list = this.list.filter((x) => x.id != nDocid);
        this.noOfRecord = this.list.length;
        this.noOfRecordChange.emit(this.noOfRecord);
        this.fds.emit('DELETE-ANNOTATION', { type: 'DELETE-ANNOTATION', id: nDocid });
      } else {
        this.tost.error(res.value);
      }
    } catch (error: any) {
      this.tost.error(error.message || 'Failed to delete');
    }
  }


  handleFeedEvent() {
    try {
      this.fds.events$
        .pipe(takeUntilDestroyed(this.destroyRef))
        .subscribe((e: SessionEvent) => {
          const { type, data } = e;
          if (type == 'QMARK-CREATED') {
            this.addQMarkToList(data);
          }
          else if (type == 'QMARK-DELETED') {
            this.removeQMarkFromList(data);
          }
          else if (type == 'QUICK-FACT-UPDATED' || type == 'FACT-ADDED') {
            // After the user updates an existing QFact (added/removed
            // issues, changed note, etc.) or converts a QFact to a Full
            // Fact, the corresponding card in this list still holds
            // the issueList from the *initial* getAll fetch — so the
            // cached chips don't reflect the new selection. Without
            // this refetch the user has to fully unmount MarkNav (or
            // the host PDF view) to see fresh data; even reopening
            // the bell-icon side panel doesn't help because the
            // session keeps navall alive when only @if() on its host
            // condition flips, and the @if(visibleMarkNavModel) host
            // does fire destroy on close, but a same-tick re-open
            // (the typical "edit then click icon again" flow) can
            // race ngOnInit. A defensive re-fetch on the update
            // event is cheap (one paged getAll call) and covers
            // every code path — RT, individual-doc, and compare
            // mode all flow through the same fds.events$ stream.
            void this.initList();
          }
        });
    } catch (error) {
      console.error(error);
    }
  }

  onViewDocLink(x) {
    this.fds.emit('VIEW-DOC-LINK', { id: x.id });
    if (this.cFFrom == 'I') {
      this.scrollFeedToPage(x);
    }
  }

  async historyInsert(x: any) {

    const history: historyBuilderMdl = {
      nBundledetailid: this.nBundledetailid,
      nSesid: this.nSesid,
      nUserid: this.nUserid,
      cType: x.cSource,
    };

    if (x.cSource == 'F' || x.cSource == 'QF') {
      history.nFSid = x.id;
    } else if (x.cSource == 'D') {
      history.nDocid = x.id;
    } else if (x.cSource == 'QM') {
      history.nHid = x.id;
    }

    const res = await this.markNavService.historyInsert(history)
    if (res.msg == 1) {
      this.bisHistorExists = true;
      this.bisHistorExistsChange.emit(this.bisHistorExists);
    }
  }


  handleFactSheetDelete(data: { nFSid: string }) {
    if (!data?.nFSid) return;
    this.list = this.list.filter((x) => x.id != data?.nFSid);
    this.noOfRecord = this.list.length;
    this.noOfRecordChange.emit(this.noOfRecord);
  }
  updateVisibleAnnotDetails(data: any) {
    try {
      if (data?.cSource == 'QM') return;
      const annotDetails: annotDetails = {
        id: data.id,
        cType: data.cSource,
      };
      this.visibleAnnotDetails = annotDetails;
      this.visibleAnnotDetailsChange.emit(this.visibleAnnotDetails);
    } catch (error) {
      console.log('er', error);

    }
  }


}
