import { Component, EventEmitter, Input, OnDestroy, Output, SimpleChanges } from '@angular/core';
import { NavDocLinkCardComponent } from "../nav-doc-link-card/nav-doc-link-card.component";
import { IconComponent } from "../../../../../shared/components/icon/icon.component";
import { markNavEvents, sortByType, viewModeType } from '../../../../interfaces/marknav.interface';
import { MarknavService } from '../../../../services/marknav/marknav.service';
import { finalFilterList } from '../../../../../shared/interfaces/filter.interface';
import { feedAnnotCordinates } from '../../../../interfaces/annotation.interface';
import { MatMenuModule } from '@angular/material/menu';
import { ButtonComponent } from "../../../../../shared/components/button/button.component";
import { RtDocsService } from '../../../../../shared/services/rt-docs/rt-docs.service';
import { FeedDisplayService } from '../../../../services/feed-display/feed-display.service';
import { FACTFROM } from '../../../../../pdf/interfaces/pdf.interface';
import { historyBuilderMdl, markNavjFilters } from '../../../../../shared/interfaces/mark-nav-filter.interface';
import { TostbarService } from '../../../../../core/services/tost/tostbar.service';
import { annotDetails } from '../../../../interfaces/feed.interface';
import { CommunicationService } from '../../../../../shared/services/communication/communication.service';
import { Subscription } from 'rxjs';

import { CommonModule } from '@angular/common';
import { TranslateModule } from '@ngx-translate/core';

@Component({
  selector: 'navdoclink',
  standalone: true, imports: [CommonModule, TranslateModule, NavDocLinkCardComponent, IconComponent, MatMenuModule, ButtonComponent],
  templateUrl: './navdoclink.component.html',
  styleUrl: './navdoclink.component.scss'
})
export class NavdoclinkComponent implements OnDestroy {
  @Input() cFFrom: FACTFROM = 'RT';
  @Input() nBundledetailid: string;
  doclist: any[] = [];
  private refreshSub: Subscription | null = null;

  @Input() viewmode: viewModeType;


  @Input() nSesid: string;
  @Input() nFSid: string;
  @Input() nUserid: string;
  @Input() isQmark: boolean;
  @Input() sortBy: sortByType;

  @Input() noOfRecord: number;
  @Output() noOfRecordChange: EventEmitter<number> = new EventEmitter<number>();

  @Input() jFilters: markNavjFilters;


  @Output() OnEvent: EventEmitter<markNavEvents> = new EventEmitter<markNavEvents>();

  @Input() historyEnabled: boolean;
  @Input() bIsTranscipt: boolean;

  @Input() visibleAnnotDetails: annotDetails;
  @Input() visibleAnnotDetailsChange: EventEmitter<annotDetails>;

  @Input() bisHistorExists: boolean;
  @Output() bisHistorExistsChange: EventEmitter<boolean> = new EventEmitter<boolean>();

  @Input() selectedIds: string[];
  @Output() selectedIdsChange: EventEmitter<string[]> = new EventEmitter<string[]>();

  constructor(private markNavService: MarknavService, private rtDoc: RtDocsService, private fds: FeedDisplayService, private tost: TostbarService, private communicationService: CommunicationService) { }

  ngOnInit(): void {
    this.initData();

    // Re-fetch DocLinks whenever the session is refreshed (REFRESH-SESSION-V2 fires from
    // FeedDisplayService when a realtime refresh event arrives). Without this, the
    // doclist held locally goes stale after refresh and DocLinks appear missing.
    this.refreshSub = this.communicationService.functionCalled$.subscribe((data: any) => {
      if (data?.event == 'REFRESH-SESSION-V2') {
        this.initData();
      }
    });
  }

  ngOnDestroy(): void {
    this.refreshSub?.unsubscribe();
  }

  async getCardEvent(e: any, x) {
    console.log(e, x)
    if (e.event == 'DOC-CARD-VIEW') {
      e.data = x;
      this.OnEvent.emit(e);
    } if (e.event == 'OPEN-COMPARE-MODE') {
      this.fds.emit(e.event, { ...e.data });
    }
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['jFilters'] && !changes['jFilters'].firstChange) {
      this.initData();
    }

    if (changes["historyEnabled"] && !changes["historyEnabled"].firstChange) {
      this.initData();
    }

    if (changes && changes['sortBy'] && !changes['sortBy'].firstChange) {
      this.initData();
    }
  }

  async initData() {
    this.doclist = [];
    const res = await this.markNavService.getDocLinkList(this.nSesid, this.nUserid, this.sortBy, this.jFilters, this.historyEnabled, this.bIsTranscipt, this.nBundledetailid);

    this.noOfRecord = res.length;
    this.noOfRecordChange.emit(this.noOfRecord);

    if (res.length) {
      this.doclist = res;
      // this.doclist.forEach((e) => {
      //   const annotPages = e?.jCordinates?.map((x: feedAnnotCordinates) => x.p) || [];
      //   const uniquePages = [...new Set(annotPages)];
      //   e.cPageno = uniquePages;
      //   e.cPageno = e.nPage;
      // })
      if (this.doclist?.length) {
        this.handleSequence(this.doclist, 'D');
      }
    }
    this.selectedIds = this.doclist.map(i => i.nDocid);
    this.selectedIdsChange.emit(this.selectedIds);

  }

  async deleteDocLink(nDocid: string) {
    try {
      const res = await this.rtDoc.deleteDoc(nDocid);
      if (res.msg == 1) {
        this.doclist = this.doclist.filter((x) => x.nDocid != nDocid);
        this.noOfRecord = this.doclist.length;
        this.noOfRecordChange.emit(this.noOfRecord);
        this.fds.emit('DELETE-ANNOTATION', { type: 'DELETE-ANNOTATION', id: nDocid });
      } else {
        this.tost.error(res.value);
      }
    } catch (error: any) {
      this.tost.error(error.message || 'Failed to delete');
    }

  }

  handleSequence(list: any[], type: string) {
    let nSequence = 0;
    let nCurrentPage = 0;
    for (const item of list) {
      item.cPageno = item.nPage;
      // if (item.cSource != type) continue;
      nSequence++;
      if ((item.nPage != nCurrentPage)) {
        nSequence = 1;
        nCurrentPage = item.nPage;
      }
      item.nSequence = nSequence;
    }
  }

  scrollFeedToPage(x: any) {
    if (x?.nPage) {
      this.fds.emit('SCROLL-TO-PAGE', { page: x.nPage, id: x.nDocid });
    } else if (x?.jLinktype?.pages) {
      this.fds.emit('SCROLL-TO-PAGE', { page: x?.jLinktype?.pages[0], id: x.nDocid });
    } else if (x?.jLinktype?.start) {
      this.fds.emit('SCROLL-TO-PAGE', { page: x?.jLinktype?.start, id: x.nDocid });
    } else {
      this.fds.emit('SCROLL-TO-PAGE', { page: 1, id: x.nDocid });
    }
  }


  async historyInsert(x: any) {
    const history: historyBuilderMdl = {
      nBundledetailid: this.nBundledetailid,
      nSesid: this.nSesid,
      nUserid: this.nUserid,
      cType: 'D',
      nDocid: x.nDocid
    };
    const res = await this.markNavService.historyInsert(history)
    if (res.msg == 1) {
      this.bisHistorExists = true;
      this.bisHistorExistsChange.emit(this.bisHistorExists);
    }
  }
  updateVisibleAnnotDetails(data: any) {
    try {
      const annotDetails: annotDetails = {
        id: data.nDocid,
        cType: 'D',
      };
      this.visibleAnnotDetails = annotDetails;
      this.visibleAnnotDetailsChange.emit(this.visibleAnnotDetails);
    } catch (error) {
      console.log('er', error);

    }
  }

}
