import { ChangeDetectorRef, Component, EventEmitter, Input, OnChanges, OnInit, OnDestroy, Output, SimpleChanges } from '@angular/core';
import { DateAdapter, MAT_DATE_FORMATS, NativeDateAdapter, provideNativeDateAdapter } from '@angular/material/core';
import { MY_DATE_FORMATS } from '../../../../adminpanel/components/transscript/transcript-properties/transcript-properties.component';
import { ButtonComponent } from '../../button/button.component';
import { IconComponent } from '../../icon/icon.component';
import { CommonModule } from '@angular/common';
import { MatMenuModule } from '@angular/material/menu';
import { NgSelectModule } from '@ng-select/ng-select';
import { FormsModule } from '@angular/forms';
import { MatCheckboxModule } from '@angular/material/checkbox';
import { MatRadioModule } from '@angular/material/radio';
import { MatSelectModule } from '@angular/material/select';
import { FactdetailfilterComponent } from '../filter-components/factdetailfilter/factdetailfilter.component';
import { FactcontactfilterComponent } from '../filter-components/factcontactfilter/factcontactfilter.component';
import { FacttaskfilterComponent } from '../filter-components/facttaskfilter/facttaskfilter.component';
import { ClaimsComponent } from "../filter-components/claims/claims.component";
import { filterItemType, filterList, markNavjFilters, navFilterTab, navFilterTabMode, FILTER_ITEM, FILTER_LIST, QFACT_DATE_TYPE, NAV_FILTER } from '../../../interfaces/mark-nav-filter.interface';
import { IssuesComponent } from "../filter-components/issues/issues.component";
import { ShareFilterComponent } from "../filter-components/share-filter/share-filter.component";
import { jDateType } from '../../../../marking/components/fact/date-form/date-form.component';
import { QfactdetailfilterComponent } from "../filter-components/qfactdetailfilter/qfactdetailfilter.component";
import { LinkfilterComponent } from "../linkfilter/linkfilter.component";

@Component({
  selector: 'navigate-filter',
  standalone: true,
  imports: [
    MatMenuModule,
    NgSelectModule,
    FormsModule,
    CommonModule,
    MatCheckboxModule,
    MatRadioModule,
    MatSelectModule,
    ButtonComponent,
    IconComponent,
    FactdetailfilterComponent,
    FactcontactfilterComponent,
    FacttaskfilterComponent,
    ClaimsComponent,
    IssuesComponent,
    ShareFilterComponent,
    QfactdetailfilterComponent,
    LinkfilterComponent
  ],
  templateUrl: './navigate-filter.component.html',
  styleUrls: ['./navigate-filter.component.scss'],
  providers: [
    provideNativeDateAdapter(),
    { provide: MAT_DATE_FORMATS, useValue: MY_DATE_FORMATS }
  ]
})
export class NavigateFilterComponent implements OnInit, OnChanges, OnDestroy {
  readonly FILTER_ITEM = FILTER_ITEM;

  @Input() nCaseid: string;
  @Input() nUserid: string;

  @Input() tab: navFilterTab;
  @Input() tabmode: navFilterTabMode;
  @Input() jCreatedBy: string[] = []

  @Input() jFilters: markNavjFilters;
  @Input() selectedTab: string;
  @Input() contactFilter: {};
  @Output() jFiltersChange: EventEmitter<markNavjFilters> = new EventEmitter<markNavjFilters>();
  @Output() closeFilter: EventEmitter<void> = new EventEmitter<void>();
  filters: filterList[] = FILTER_LIST;


  qfactdatetype = QFACT_DATE_TYPE;

  selectedFilters: filterItemType[] = [];


  jClaims: string[] = [];

  jLevels: any;

  jIssues: string[] = [];
  jRels: number[] = [];
  jImps: number[] = [];

  IsNote: boolean = false;
  IsFactlink: boolean = false;
  IsComment: boolean = false;


  jDate: jDateType;
  jFiletypes: number[] = [];
  jStatus: number[] = [];
  createDate: { start: string, end: string };
  createBy: string[] = [];


  jContacts: string[] = [];
  jCRoles: string[] = [];
  jCPartys: number[] = [];
  jCCompanies: string[] = [];
  IsContactNote: boolean = false;


  jTasks: string[] = [];
  IsTaskDesc: boolean = false;
  jTShared: string[] = [];
  jTStatus: number[] = [];
  jTPriority: number[] = [];
  dTDate: string = '';


  IsCreateByMe: boolean = false;
  IsShared: boolean = false;

  // Backup of original filter state for cancel functionality
  private originalFilters: {
    selectedFilters: filterItemType[];
    jClaims: string[];
    jIssues: string[];
    jRels: number[];
    jImps: number[];
    IsNote: boolean;
    IsFactlink: boolean;
    IsComment: boolean;
    jDate: jDateType;
    jFiletypes: number[];
    jStatus: number[];
    jLevels: any;
    createDate: { start: string, end: string };
    createBy: string[];
    jContacts: string[];
    jCRoles: string[];
    jCPartys: number[];
    jCCompanies: string[];
    IsContactNote: boolean;
    jTasks: string[];
    IsTaskDesc: boolean;
    jTShared: string[];
    jTStatus: number[];
    jTPriority: number[];
    dTDate: string;
    IsCreateByMe: boolean;
    IsShared: boolean;
  };

  // flag to indicate component destroyed state
  private destroyed = false;

  constructor(private readonly cdr: ChangeDetectorRef) { }

  ngOnInit() {
    // Load existing filters when component initializes
    if (this.jFilters) {
      this.loadExistingFilters();
    }
    // Create backup of the current state for cancel functionality
    this.backupCurrentState();
  }

  ngOnChanges(changes: SimpleChanges): void {
    //Called before any other lifecycle hook. Use it to inject dependencies, but avoid any serious work here.
    //Add '${implements OnChanges}' to the class.
    if (changes['jFilters'] && this.jFilters) {
      this.loadExistingFilters();
      // Update backup with the new saved state
      this.backupCurrentState();
    }
  }

  loadExistingFilters() {
    // Load existing filter values when component initializes or jFilters changes
    if (this.jFilters) {
      this.jClaims = this.jFilters.jClaims || [];
      this.jIssues = this.jFilters.jIssues || [];
      this.jRels = this.jFilters.jRels || [];
      this.jImps = this.jFilters.jImps || [];
      this.IsNote = this.jFilters.IsNote || false;
      this.IsFactlink = this.jFilters.IsFactlink || false;
      this.IsComment = this.jFilters.IsComment || false;
      this.jDate = this.jFilters.jDate;
      this.jFiletypes = this.jFilters.jFiletypes || [];
      this.jStatus = this.jFilters.jStatus || [];
      this.jLevels = this.jFilters.cType;
      this.createDate = this.jFilters.createDate;
      this.createBy = this.jFilters.createBy || [];
      this.jContacts = this.jFilters.jContacts || [];
      this.jCRoles = this.jFilters.jCRoles || [];
      this.jCPartys = this.jFilters.jCPartys || [];
      this.jCCompanies = this.jFilters.jCCompanies || [];
      this.IsContactNote = this.jFilters.IsContactNote || false;
      this.jTasks = this.jFilters.jTasks || [];
      this.IsTaskDesc = this.jFilters.IsTaskDesc || false;
      this.jTShared = this.jFilters.jTShared || [];
      this.jTStatus = this.jFilters.jTStatus || [];
      this.jTPriority = this.jFilters.jTPriority || [];
      this.dTDate = this.jFilters.dTDate || '';
      this.IsCreateByMe = this.jFilters.IsCreateByMe || false;
      this.IsShared = this.jFilters.IsShared || false;

      // Set selected filters based on what exists in jFilters
      this.setSelectedFilters();

      // Force change detection to ensure child components receive updated values
      Promise.resolve().then(() => this.cdr.detectChanges());
    }
  }

  private setSelectedFilters(): void {
    this.selectedFilters = [];
    if (this.jClaims?.length) this.selectedFilters.push(this.FILTER_ITEM.CL);

    const hasIssueData = !!(this.jIssues?.length || this.jRels?.length || this.jImps?.length || this.IsNote || this.IsFactlink || this.IsComment);
    if (hasIssueData) this.selectedFilters.push(this.FILTER_ITEM.I);

    const hasFactData = !!(this.jDate || this.jFiletypes?.length || this.jStatus?.length || this.jLevels || this.createDate);
    if (hasFactData) this.selectedFilters.push(this.FILTER_ITEM.FD);

    const hasContactData = !!(this.jContacts?.length || this.jCRoles?.length || this.jCPartys?.length || this.jCCompanies?.length || this.IsContactNote);
    if (hasContactData) this.selectedFilters.push(this.FILTER_ITEM.C);

    const hasTaskData = !!(this.jTasks?.length || this.IsTaskDesc || this.jTShared?.length || this.jTStatus?.length || this.jTPriority?.length || this.dTDate);
    if (hasTaskData) this.selectedFilters.push(this.FILTER_ITEM.T);

    if (this.IsCreateByMe || this.IsShared) this.selectedFilters.push(this.FILTER_ITEM.S);

    if (this.createDate && (this.tab === NAV_FILTER.QF || this.selectedTab === NAV_FILTER.QF)) this.selectedFilters.push(this.FILTER_ITEM.QF);
    if (this.createDate && (this.tab === NAV_FILTER.QM || this.selectedTab === NAV_FILTER.QM)) this.selectedFilters.push(this.FILTER_ITEM.QM);
  }

  backupCurrentState() {
    // Create a deep copy of the current filter state for cancel functionality
    this.originalFilters = {
      selectedFilters: [...this.selectedFilters],
      jClaims: [...this.jClaims],
      jIssues: [...this.jIssues],
      jRels: [...this.jRels],
      jImps: [...this.jImps],
      IsNote: this.IsNote,
      IsFactlink: this.IsFactlink,
      IsComment: this.IsComment,
      jDate: this.jDate ? { ...this.jDate } : null,
      jFiletypes: [...this.jFiletypes],
      jStatus: [...this.jStatus],
      jLevels: this.jLevels,
      createDate: this.createDate ? { ...this.createDate } : null,
      createBy: [...this.createBy],
      jContacts: [...this.jContacts],
      jCRoles: [...this.jCRoles],
      jCPartys: [...this.jCPartys],
      jCCompanies: [...this.jCCompanies],
      IsContactNote: this.IsContactNote,
      jTasks: [...this.jTasks],
      IsTaskDesc: this.IsTaskDesc,
      jTShared: [...this.jTShared],
      jTStatus: [...this.jTStatus],
      jTPriority: [...this.jTPriority],
      dTDate: this.dTDate,
      IsCreateByMe: this.IsCreateByMe,
      IsShared: this.IsShared
    };
  }


  clearAllFilter() {
    this.selectedFilters = [];
    this.jIssues = [];
    this.jClaims = [];
    this.jRels = [];
    this.jImps = [];
    this.jFilters = {} as markNavjFilters;
    this.jFiltersChange.emit(this.jFilters);
  }


  addfilter(x: filterList) {
    const index = this.selectedFilters.indexOf(x.value);
    if (index > -1) {
      this.selectedFilters.splice(index, 1);
    } else {
      this.selectedFilters.push(x.value);
    }
  }


  removeall(flag: filterItemType) {
    const index = this.selectedFilters.indexOf(flag);
    if (index > -1) {
      this.selectedFilters.splice(index, 1);
    }
  }


  saveFilter(closeDialog: boolean): void {
    this.jFilters = {} as markNavjFilters;

    this.processClaims();
    this.processIssues();
    this.processDateAndLevels();
    this.processContacts();
    this.processTasks();
    this.processSharing();
    this.processQM();

    this.cleanupEmptyFilters();

    if (this.jCreatedBy?.length) {
      this.jFilters.createBy = this.jCreatedBy;
    } else {
      delete this.jFilters.createBy;
    }

    if (Object.keys(this.jFilters).length === 0) {
      this.jFilters = null;
    }

    this.jFiltersChange.emit(this.jFilters);

    this.backupCurrentState();

    if (closeDialog) {
      this.closeFilter.emit();
    }
  }

  private processClaims(): void {
    if (this.selectedFilters.includes('CL')) {
      if (this.jClaims?.length) {
        this.jFilters.jClaims = this.jClaims;
      } else if (this.jFilters.jClaims) {
        delete this.jFilters.jClaims;
      }
    } else {
      delete this.jFilters.jClaims;
    }
  }

  private processIssues(): void {
    if (!this.selectedFilters.includes(this.FILTER_ITEM.I)) {
      delete this.jFilters.jIssues;
      delete this.jFilters.jRels;
      delete this.jFilters.jImps;
      delete this.jFilters.IsNote;
      delete this.jFilters.IsFactlink;
      delete this.jFilters.IsComment;
      return;
    }

    if (this.jIssues?.length) this.jFilters.jIssues = this.jIssues; else delete this.jFilters.jIssues;
    if (this.jRels?.length) this.jFilters.jRels = this.jRels; else delete this.jFilters.jRels;
    if (this.jImps?.length) this.jFilters.jImps = this.jImps; else delete this.jFilters.jImps;

    if (this.IsNote) this.jFilters.IsNote = this.IsNote; else delete this.jFilters.IsNote;
    if (this.IsFactlink) this.jFilters.IsFactlink = this.IsFactlink; else delete this.jFilters.IsFactlink;
    if (this.IsComment) this.jFilters.IsComment = this.IsComment; else delete this.jFilters.IsComment;
  }

  private processDateAndLevels(): void {
    if (!(this.selectedFilters.includes(FILTER_ITEM.FD) || this.selectedFilters.includes(FILTER_ITEM.QF))) return;

    if (!this.selectedFilters.includes(FILTER_ITEM.QF)) {
      this.setNonQFDateFields();
    }

    this.setCreateDateAndBy();
    this.setLevels();
    this.cleanupFDandQF();
  }

  private setNonQFDateFields(): void {
    if (this.jDate) this.jFilters.jDate = this.jDate; else delete this.jFilters.jDate;
    if (this.jFiletypes?.length) this.jFilters.jFiletypes = this.jFiletypes; else delete this.jFilters.jFiletypes;
    if (this.jStatus?.length) this.jFilters.jStatus = this.jStatus; else delete this.jFilters.jStatus;
  }

  private setCreateDateAndBy(): void {
    if (this.createDate) this.jFilters.createDate = this.createDate; else delete this.jFilters.createDate;
    if (this.createBy?.length) this.jFilters.createBy = this.createBy; else delete this.jFilters.createBy;
  }

  private setLevels(): void {
    if (this.jLevels) {
      const filter = { cType: this.jLevels };
      this.jFilters = { ...this.jFilters, ...filter };
    }
  }

  private cleanupFDandQF(): void {
    if (!this.selectedFilters.includes(FILTER_ITEM.FD)) {
      delete this.jFilters.jDate;
      delete this.jFilters.jFiletypes;
      delete this.jFilters.jStatus;
    }
    if (!this.selectedFilters.includes(FILTER_ITEM.QF) && !this.selectedFilters.includes(FILTER_ITEM.FD)) {
      delete this.jFilters.createDate;
      delete this.jFilters.createBy;
    }
  }

  private processContacts(): void {
    if (!this.selectedFilters.includes(this.FILTER_ITEM.C)) {
      delete this.jFilters.jContacts;
      delete this.jFilters.jCRoles;
      delete this.jFilters.jCPartys;
      delete this.jFilters.jCCompanies;
      delete this.jFilters.IsContactNote;
      return;
    }

    if (this.jContacts?.length) this.jFilters.jContacts = this.jContacts; else delete this.jFilters.jContacts;
    if (this.jCRoles?.length) this.jFilters.jCRoles = this.jCRoles; else delete this.jFilters.jCRoles;
    if (this.jCPartys?.length) this.jFilters.jCPartys = this.jCPartys; else delete this.jFilters.jCPartys;
    if (this.jCCompanies?.length) this.jFilters.jCCompanies = this.jCCompanies; else delete this.jFilters.jCCompanies;
    if (this.IsContactNote) this.jFilters.IsContactNote = this.IsContactNote; else delete this.jFilters.IsContactNote;
  }

  private processTasks(): void {
    if (!this.selectedFilters.includes(this.FILTER_ITEM.T)) {
      delete this.jFilters.jTasks;
      delete this.jFilters.IsTaskDesc;
      delete this.jFilters.jTShared;
      delete this.jFilters.jTStatus;
      delete this.jFilters.jTPriority;
      delete this.jFilters.dTDate;
      return;
    }

    if (this.jTasks?.length) this.jFilters.jTasks = this.jTasks; else delete this.jFilters.jTasks;
    if (this.IsTaskDesc) this.jFilters.IsTaskDesc = this.IsTaskDesc; else delete this.jFilters.IsTaskDesc;
    if (this.jTShared?.length) this.jFilters.jTShared = this.jTShared; else delete this.jFilters.jTShared;
    if (this.jTStatus?.length) this.jFilters.jTStatus = this.jTStatus; else delete this.jFilters.jTStatus;
    if (this.jTPriority?.length) this.jFilters.jTPriority = this.jTPriority; else delete this.jFilters.jTPriority;
    if (this.dTDate) this.jFilters.dTDate = this.dTDate; else delete this.jFilters.dTDate;
  }

  private processSharing(): void {
    if (!this.selectedFilters.includes('S')) {
      delete this.jFilters.IsCreateByMe;
      delete this.jFilters.IsShared;
      return;
    }

    if (this.IsCreateByMe) this.jFilters.IsCreateByMe = this.IsCreateByMe; else delete this.jFilters.IsCreateByMe;
    if (this.IsShared) this.jFilters.IsShared = this.IsShared; else delete this.jFilters.IsShared;
  }

  private processQM(): void {
    if (this.selectedFilters.includes(this.FILTER_ITEM.QM)) {
      if (this.createDate) this.jFilters.createDate = this.createDate; else delete this.jFilters.createDate;
    } else if (!this.selectedFilters.includes(FILTER_ITEM.FD) && !this.selectedFilters.includes(FILTER_ITEM.QF)) {
      delete this.jFilters.createDate;
    }
  }

  private cleanupEmptyFilters(): void {
    Object.keys(this.jFilters).forEach((element) => {
      // @ts-ignore indexed access preserved from original logic
      if (!this.jFilters[element] || (Array.isArray(this.jFilters[element]) && !this.jFilters[element]?.length)) {
        // @ts-ignore allow dynamic deletion
        delete this.jFilters[element];
      }
    });
  }

  cancelFilter() {
    if (this.originalFilters) {
      this.restoreOriginalFilters();
    }

    this.closeFilter.emit();
  }

  private restoreOriginalFilters(): void {
    this.selectedFilters = [...this.originalFilters.selectedFilters];
    this.jClaims = [...this.originalFilters.jClaims];
    this.jIssues = [...this.originalFilters.jIssues];
    this.jRels = [...this.originalFilters.jRels];
    this.jImps = [...this.originalFilters.jImps];
    this.IsNote = this.originalFilters.IsNote;
    this.IsFactlink = this.originalFilters.IsFactlink;
    this.IsComment = this.originalFilters.IsComment;
    this.jDate = this.originalFilters.jDate ? { ...this.originalFilters.jDate } : null;
    this.jFiletypes = [...this.originalFilters.jFiletypes];
    this.jStatus = [...this.originalFilters.jStatus];
    this.jLevels = this.originalFilters.jLevels;
    this.createDate = this.originalFilters.createDate ? { ...this.originalFilters.createDate } : null;
    this.createBy = [...this.originalFilters.createBy];
    this.jContacts = [...this.originalFilters.jContacts];
    this.jCRoles = [...this.originalFilters.jCRoles];
    this.jCPartys = [...this.originalFilters.jCPartys];
    this.jCCompanies = [...this.originalFilters.jCCompanies];
    this.IsContactNote = this.originalFilters.IsContactNote;
    this.jTasks = [...this.originalFilters.jTasks];
    this.IsTaskDesc = this.originalFilters.IsTaskDesc;
    this.jTShared = [...this.originalFilters.jTShared];
    this.jTStatus = [...this.originalFilters.jTStatus];
    this.jTPriority = [...this.originalFilters.jTPriority];
    this.dTDate = this.originalFilters.dTDate;
    this.IsCreateByMe = this.originalFilters.IsCreateByMe;
    this.IsShared = this.originalFilters.IsShared;

    this.cdr.detectChanges();
  }

  emitFilters(){
    // Build and emit current filters without closing the filter panel
    this.saveFilter(false);
  }

  ngOnDestroy(): void {
    // mark destroyed and release large references to aid GC and satisfy lifecycle checks
    this.destroyed = true;

    this.selectedFilters = [];
    this.jClaims = [];
    this.jIssues = [];
    this.jRels = [];
    this.jImps = [];
    this.jFiletypes = [];
    this.jStatus = [];
    this.createBy = [];
    this.jContacts = [];
    this.jCRoles = [];
    this.jCPartys = [];
    this.jCCompanies = [];
    this.jTasks = [];
    this.jTShared = [];
    this.jTStatus = [];
    this.jTPriority = [];

    this.jFilters = null;
  }

}

