import { booleanAttribute, Component, EventEmitter, Input, Output } from '@angular/core';
import { IssueDetail, LinkDetail, markNavEvents, navigateModeType, viewModeType } from '../../../../interfaces/marknav.interface';
import { Subject } from 'rxjs';
import { finalFilterList } from '../../../../../shared/interfaces/filter.interface';
import { MarknavService } from '../../../../services/marknav/marknav.service';
import { FACTFROM } from '../../../../../pdf/interfaces/pdf.interface';
import { CommonModule, DatePipe } from '@angular/common';
import { TranslateModule } from '@ngx-translate/core';
import { SourceCardComponent } from '../../../../../shared/components/source-card/source-card.component';
import { SelectedIssuesComponent } from '../../../../../shared/components/issues/selected-issues/selected-issues.component';
import { ButtonComponent } from '../../../../../shared/components/button/button.component';
import { IconComponent } from '../../../../../shared/components/icon/icon.component';
import { AvatarComponent } from '../../../../../shared/components/avatar/avatar.component';
import { FactboxComponent } from '../../../../../pdf/components/facts/factbox/factbox.component';
import { MatTooltipModule } from '@angular/material/tooltip';
import { NavFactViewModelComponent } from "../nav-fact-view-model/nav-fact-view-model.component";
import { FeedDisplayService } from '../../../../services/feed-display/feed-display.service';
import { MatMenu, MatMenuTrigger } from '@angular/material/menu';
import { FactcardComponent } from '../../../../../pdf/components/linkviews/facts/factcard/factcard.component';

@Component({
  selector: 'navfact-link',
  standalone: true,
  imports: [ButtonComponent, IconComponent, CommonModule, TranslateModule, MatTooltipModule, NavFactViewModelComponent, MatMenuTrigger, MatMenu, FactcardComponent],
  templateUrl: './navfact-link.component.html',
  styleUrl: './navfact-link.component.scss'
})
export class NavfactLinkComponent {


  @Input() viewmode: viewModeType;

  @Input() cFFrom: FACTFROM = 'RT';
  @Input() nBundledetailid: string;
  @Input() nCaseid: string;
  @Input() nSesid: string;
  @Input() nUserid: string;
  @Input() sortBy: string = 'desc';
  @Input() onNavigateEvent: Subject<markNavEvents>;
  @Input() selectedMode: navigateModeType;


  @Input() noOfRecord: number;
  @Output() noOfRecordChange: EventEmitter<number> = new EventEmitter<number>();

  factlist: any = [];
  jFilter: finalFilterList[] = [];

  @Input() historyEnabled: boolean;
  @Input() bIsTranscipt: boolean;

  constructor(private markNavService: MarknavService, private fds: FeedDisplayService) { }


  ngOnInit(): void {
    //Called after the constructor, initializing input properties, and the first call to ngOnChanges.
    //Add 'implements OnInit' to the class.
    this.getFactLinkList(1);

    this.noOfRecord = 0;
    this.noOfRecordChange.emit(this.noOfRecord);

    if (this.onNavigateEvent) {
      this.onNavigateEvent.subscribe((e: markNavEvents) => {
        if (e.event == 'FILTER' && this.selectedMode == 'FL') {
          this.jFilter = e.data;
          this.getFactLinkList(1);
        }
      });
    }
  }

  async getFactLinkList(pageNo) {
    let res: any = await this.markNavService.getFactlinklist(this.nSesid, this.nUserid, this.sortBy, pageNo, this.jFilter, this.historyEnabled, this.bIsTranscipt, this.nBundledetailid);
    // if (pageNo > 1) {
    //   this.factlist = [...this.factlist, ...res[0]];
    // } else {
    // this.factlist = res && res.length ? res[0] : [];
    // }
    // this.noOfRecord = this.factlist.length;
    console.log('res', res);

    this.handleFactLinks(res);
  }

  handleFactLinks(res: any) {
    this.factlist = res && res.length ? res[0] : [];
    this.noOfRecord = this.factlist.length;
    this.noOfRecordChange.emit(this.noOfRecord);
    let IssueDetail: IssueDetail[] = res[1] || [];


    let LinkDetail: LinkDetail[] = res[2] || [];
    let usedLinkDetailIndexes: Set<number> = new Set();


    LinkDetail.sort((a, b) => a.cName?.localeCompare(b.cName, undefined, { sensitivity: 'base' }));

    this.factlist.forEach((element) => {
      const matchingIndex = LinkDetail.findIndex((link, idx) =>
        link.nFSid === element.nFSid && !usedLinkDetailIndexes.has(idx)
      );

      if (matchingIndex !== -1) {
        element.linkfile = [LinkDetail[matchingIndex]];
        usedLinkDetailIndexes.add(matchingIndex);
      } else {
        element.linkfile = []; // no matching unused file
      }

      // Issue mapping remains unchanged
      element.issueList = IssueDetail.filter(x => x.jFSids.includes(element.nFSid));
    });
  }




  scrollFeedToPage(x: any) {
    if (x?.nPage) {
      this.fds.emit('SCROLL-TO-PAGE', { page: x.nPage, id: x.id });
    } else if (x?.jLinktype?.pages) {
      this.fds.emit('SCROLL-TO-PAGE', { page: x?.jLinktype?.pages[0], id: x.id });
    } else if (x?.jLinktype?.start) {
      this.fds.emit('SCROLL-TO-PAGE', { page: x?.jLinktype?.start, id: x.id });
    } else {
      this.fds.emit('SCROLL-TO-PAGE', { page: 1, id: x.id });
    }
  }

  factCardEvent(event, item) {

  }
}

