import { Directive, ElementRef, HostListener, Input, OnInit, OnDestroy } from '@angular/core';

@Directive({
  standalone: true,
  selector: '[appAutoGrowInput]'
})
export class AutoGrowInputDirective implements OnInit, OnDestroy {
  @Input() minRows: number = 1;
  @Input() maxRows: number = 10;
  @Input() lineHeight: number = 20; // Default line height in pixels
  @Input() minWidth: number = 100; // Minimum width for input elements
  @Input() maxWidth: number = 500; // Maximum width for input elements

  private observer?: ResizeObserver;
  private isResizing: boolean = false;
  private isInput: boolean = false;

  constructor(private elementRef: ElementRef<HTMLInputElement | HTMLTextAreaElement>) {}

  ngOnInit(): void {
    this.isInput = this.elementRef.nativeElement.tagName.toLowerCase() === 'input';
    this.setupAutoGrow();
    
    // Use setTimeout to ensure the element is fully rendered before adjusting size
    setTimeout(() => {
      this.adjustSize();
    }, 0);
  }

  ngOnDestroy(): void {
    if (this.observer) {
      this.observer.disconnect();
    }
  }

  @HostListener('input', ['$event'])
  onInput(event: Event): void {
    this.adjustSize();
  }

  @HostListener('paste', ['$event'])
  onPaste(event: ClipboardEvent): void {
    // Use setTimeout to ensure the paste content is processed
    setTimeout(() => {
      this.adjustSize();
    }, 0);
  }

  @HostListener('keydown', ['$event'])
  onKeyDown(event: KeyboardEvent): void {
    // Handle Enter key for better UX
    if (event.key === 'Enter' && !event.shiftKey) {
      // Allow default behavior for Enter key
      setTimeout(() => {
        this.adjustSize();
      }, 0);
    }
  }

  @HostListener('ngModelChange', ['$event'])
  onModelChange(value: any): void {
    // Handle programmatic value changes
    setTimeout(() => {
      this.adjustSize();
    }, 0);
  }

  private setupAutoGrow(): void {
    const element = this.elementRef.nativeElement;
    
    // Set initial styles
    element.style.overflow = 'hidden';
    element.style.boxSizing = 'border-box';
    
    if (this.isInput) {
      // For input elements, set width constraints and fix height
      element.style.resize = 'none';
      element.style.minWidth = `${this.minWidth}px`;
      element.style.maxWidth = `${this.maxWidth}px`;
      element.style.width = 'auto';
      element.style.height = 'auto'; // Ensure height doesn't change
      element.style.overflowY = 'hidden'; // Prevent vertical scrolling
    } else {
      // For textarea elements, set height constraints
      element.style.resize = 'none';
      const minHeight = this.minRows * this.lineHeight;
      element.style.minHeight = `${minHeight}px`;
      const maxHeight = this.maxRows * this.lineHeight;
      element.style.maxHeight = `${maxHeight}px`;
    }

    // Set up ResizeObserver for external changes
    if (window.ResizeObserver) {
      this.observer = new ResizeObserver(() => {
        if (!this.isResizing) {
          this.adjustSize();
        }
      });
      this.observer.observe(element);
    }
  }

  private adjustSize(): void {
    if (this.isResizing) return;
    
    this.isResizing = true;
    const element = this.elementRef.nativeElement;
    
    if (this.isInput) {
      this.adjustInputWidth(element as HTMLInputElement);
    } else {
      this.adjustTextareaHeight(element as HTMLTextAreaElement);
    }
    
    // Reset the flag
    setTimeout(() => {
      this.isResizing = false;
    }, 0);
  }

  private adjustInputWidth(input: HTMLInputElement): void {
    // Store current height to ensure it doesn't change
    const currentHeight = input.style.height || input.offsetHeight + 'px';
    
    // Get the text content to measure (prioritize value over placeholder)
    const textToMeasure = input.value || input.placeholder || '';
    
    // If there's no text to measure, set minimum width
    if (!textToMeasure.trim()) {
      input.style.width = `${this.minWidth}px`;
      input.style.height = currentHeight;
      return;
    }
    
    // Create a temporary element to measure text width
    const tempElement = document.createElement('span');
    const computedStyle = window.getComputedStyle(input);
    
    // Copy all relevant styles to the temporary element for accurate measurement
    tempElement.style.position = 'absolute';
    tempElement.style.visibility = 'hidden';
    tempElement.style.whiteSpace = 'nowrap';
    tempElement.style.font = computedStyle.font;
    tempElement.style.fontSize = computedStyle.fontSize;
    tempElement.style.fontFamily = computedStyle.fontFamily;
    tempElement.style.fontWeight = computedStyle.fontWeight;
    tempElement.style.fontStyle = computedStyle.fontStyle;
    tempElement.style.letterSpacing = computedStyle.letterSpacing;
    tempElement.style.textTransform = computedStyle.textTransform;
    tempElement.style.paddingLeft = computedStyle.paddingLeft;
    tempElement.style.paddingRight = computedStyle.paddingRight;
    tempElement.style.borderLeftWidth = computedStyle.borderLeftWidth;
    tempElement.style.borderRightWidth = computedStyle.borderRightWidth;
    tempElement.style.boxSizing = computedStyle.boxSizing;
    
    // Set the text content
    tempElement.textContent = textToMeasure;
    
    // Add to DOM temporarily
    document.body.appendChild(tempElement);
    
    // Get the measured width
    const textWidth = tempElement.getBoundingClientRect().width;
    
    // Clean up
    document.body.removeChild(tempElement);
    
    // Calculate new width within bounds (add some padding for better UX)
    const padding = 20; // Extra padding for cursor and visual comfort
    const newWidth = Math.max(this.minWidth, Math.min(textWidth + padding, this.maxWidth));
    
    // Apply the new width
    input.style.width = `${newWidth}px`;
    
    // Ensure height remains unchanged
    input.style.height = currentHeight;
  }

  private adjustTextareaHeight(textarea: HTMLTextAreaElement): void {
    // Store current scroll position
    const scrollTop = textarea.scrollTop;
    
    // Reset height to auto to get the correct scrollHeight
    textarea.style.height = 'auto';
    
    // Calculate the new height
    const scrollHeight = textarea.scrollHeight;
    const minHeight = this.minRows * this.lineHeight;
    const maxHeight = this.maxRows * this.lineHeight;
    
    // Apply the calculated height within min/max bounds
    const newHeight = Math.max(minHeight, Math.min(scrollHeight, maxHeight));
    textarea.style.height = `${newHeight}px`;
    
    // Restore scroll position
    textarea.scrollTop = scrollTop;
  }

  // Public method to manually trigger size adjustment
  public resize(): void {
    this.adjustSize();
  }

  // Public method to handle programmatic value changes
  public updateSize(): void {
    setTimeout(() => {
      this.adjustSize();
    }, 0);
  }
}
