import { ChangeDetectorRef, Component, EventEmitter, Input, Output, SimpleChanges } from '@angular/core';
import { markingDetailMode } from '../../../../interfaces/marknav.interface';
import { selectedContactList, selectedTaskList } from '../../../../../shared/interfaces/issue.interface';
import { docItem } from '../../../../../shared/interfaces/doc.interface';
import { myTeamUsers } from '../../../../../marking/interfaces/teamshare.interface';
import { EmptyComponent } from "../../../../../shared/components/empty/empty.component";
import { NavSharePermissionComponent } from "../nav-share-permission/nav-share-permission.component";
import { RtDocsService } from '../../../../../shared/services/rt-docs/rt-docs.service';
import { CommonService } from '../../../../../shared/services/common/common.service';
import { IconComponent } from '../../../../../shared/components/icon/icon.component';
import { QuickPreviewComponent } from "../../../../../userpanel/components/quick-preview/quick-preview.component";

import { CommonModule } from '@angular/common';

import { TranslateModule } from '@ngx-translate/core';

@Component({
  selector: 'nav-doc-view-model',
  standalone: true,
  imports: [CommonModule, EmptyComponent, NavSharePermissionComponent, IconComponent, QuickPreviewComponent, TranslateModule],
  templateUrl: './nav-doc-view-model.component.html',
  styleUrl: './nav-doc-view-model.component.scss'
})
export class NavDocViewModelComponent {

  @Input() detailViewMode: markingDetailMode;
  @Input() docData: docItem;
  @Input() nUserid: string;
  @Input() nCaseid: string;
  @Input() isIndividual: boolean = false;

  userList: myTeamUsers[] = [];

  selectedContacts: selectedContactList[] = [];

  @Input() selectedTab: string = 'L';

  @Input() isFullViewLoading: boolean = false;
  @Output() isFullViewLoadingChange: EventEmitter<boolean> = new EventEmitter<boolean>();

  @Output() closeEvent: EventEmitter<boolean> = new EventEmitter<boolean>();

  showsource: boolean = false;

  constructor(private rtDocService: RtDocsService, private common: CommonService, private cdr: ChangeDetectorRef) { }

  ngOnInit() {
    this.handleFullViewDetails();
  }


  ngOnChanges(changes: SimpleChanges) {

    if ((changes['docData'] && !changes['docData'].firstChange) || (changes['detailViewMode'] && !changes['detailViewMode'].firstChange)) {
      this.handleFullViewDetails();
    }
  }

  async handleFullViewDetails() {

    if (this.isFullViewLoading) {
      return;
    }
    this.isFullViewLoading = true;
    this.isFullViewLoadingChange.emit(this.isFullViewLoading);
    if (this.detailViewMode == 'S') {
      this.userList = await this.common.getMyTeamUsers(this.nCaseid);
      const res = await this.rtDocService.getDocShare(this.docData?.id || this.docData?.nDocid);
      this.handleSharedUsers(this.userList, res);
    }
    else if (this.detailViewMode == 'ST' && this.docData?.cType == 'M') {
      this.showsource = true;
    }

    this.isFullViewLoading = false;
    this.isFullViewLoadingChange.emit(this.isFullViewLoading);
  }


  handleSharedUsers(users: myTeamUsers[], sharedUsers: myTeamUsers[]) {

    if (!users?.length || !sharedUsers?.length) return;

    users.map(f => {
      const sharedUser = sharedUsers.find(m => m.nUserid == f.nUserid);
      if (sharedUser) {
        f.isSelected = true;
        f.bCanEdit = sharedUser.bCanEdit;
        f.bCanCopy = sharedUser.bCanCopy;
        f.bCanReshare = sharedUser.bCanReshare;
        f.bCanComment = sharedUser.bCanComment;
      }
    })
  }

  close() {
    this.isFullViewLoading = false;
    this.isFullViewLoadingChange.emit(this.isFullViewLoading);
    this.closeEvent.emit(true);
    this.cdr.detectChanges();
  }


  deselect() {
    this.showsource = false;
    this.close();
  }

  OnQuickPreviewEvent(e) {

  }

}
