// search-shared.service.ts
import { Injectable } from '@angular/core';
import { BehaviorSubject } from 'rxjs';

export interface MatchEntry {
  issueId: string | number;      // <-- stable key, e.g. x.nIid
  occurrenceInIssue: number;     // <-- 1..N inside that issue
  // Optional hint to enforce UI list order when available
  orderHint?: number;            // smaller comes first
}

@Injectable({ providedIn: 'root' })
export class SearchSharedService {
  private searchTermSource = new BehaviorSubject<string>('');
  private wholeWordSource  = new BehaviorSubject<boolean>(false);

  private totalMatchesSource  = new BehaviorSubject<number>(0);
  private currentMatchSource  = new BehaviorSubject<number>(0);         // 1-based
  private matchIndexesSource  = new BehaviorSubject<MatchEntry[]>([]);  // ordered
  
  // Optional ordering: map issueId -> rank based on current UI list
  private issueOrderMap = new Map<string | number, number>();

  // Observables
  searchTerm$    = this.searchTermSource.asObservable();
  wholeWord$     = this.wholeWordSource.asObservable();
  totalMatches$  = this.totalMatchesSource.asObservable();
  currentMatch$  = this.currentMatchSource.asObservable();
  matchIndexes$  = this.matchIndexesSource.asObservable();

  // Safe getters
  get searchTermValue()   { return this.searchTermSource.value; }
  get wholeWordValue()    { return this.wholeWordSource.value; }
  get totalMatchesValue() { return this.totalMatchesSource.value; }
  get currentMatchValue() { return this.currentMatchSource.value; }
  get matchIndexesValue() { return this.matchIndexesSource.value; }

  setSearchTerm(term: string) {
    this.searchTermSource.next(term);
    this.clearMatches();
  }
  setWholeWord(flag: boolean) {
    this.wholeWordSource.next(flag);
  }

  setMatches(list: MatchEntry[]) {
    const decorated: Array<{entry: MatchEntry; idx: number}> = list.map((entry, idx) => ({ entry, idx }));
    const rankOf = (issueId: string | number): number => {
      const mapped = this.issueOrderMap.get(issueId);
      return typeof mapped === 'number' ? mapped : Number.POSITIVE_INFINITY;
    };
    decorated.sort((a, b) => {
      // 1) Prefer provided orderHint if present
      const ah = a.entry.orderHint;
      const bh = b.entry.orderHint;
      if (typeof ah === 'number' && typeof bh === 'number' && ah !== bh) {
        return ah - bh;
      }
      if (typeof ah === 'number' && typeof bh !== 'number') return -1;
      if (typeof ah !== 'number' && typeof bh === 'number') return 1;

      // 2) Otherwise, use issueOrderMap rank when available
      const ar = rankOf(a.entry.issueId);
      const br = rankOf(b.entry.issueId);
      if (ar !== br) return ar - br;

      // 3) Fallback: natural compare of issueId (stringified)
      const as = String(a.entry.issueId);
      const bs = String(b.entry.issueId);
      if (as !== bs) return as < bs ? -1 : 1;

      // 4) Then occurrence within issue
      if (a.entry.occurrenceInIssue !== b.entry.occurrenceInIssue) {
        return a.entry.occurrenceInIssue - b.entry.occurrenceInIssue;
      }

      // 5) Stable fallback: original index
      return a.idx - b.idx;
    });

    const ordered = decorated.map(d => d.entry);
    this.matchIndexesSource.next(ordered);
    this.totalMatchesSource.next(ordered.length);
    this.currentMatchSource.next(ordered.length ? 1 : 0); // start at first
  }

  setCurrentMatch(index: number) {
    this.currentMatchSource.next(index);
  }

  nextMatch() {
    const cur = this.currentMatchValue, tot = this.totalMatchesValue;
    if (tot > 0 && cur < tot) this.setCurrentMatch(cur + 1);
  }
  previousMatch() {
    const cur = this.currentMatchValue;
    if (cur > 1) this.setCurrentMatch(cur - 1);
  }

  clearMatches() {
    this.matchIndexesSource.next([]);
    this.totalMatchesSource.next(0);
    this.currentMatchSource.next(0);
  }

  // Public API: set the UI list order for issues so navigation follows it
  setIssueOrder(issueIdsInOrder: Array<string | number>) {
    this.issueOrderMap.clear();
    issueIdsInOrder.forEach((id, idx) => this.issueOrderMap.set(id, idx));
    // Re-sort existing matches to respect new order
    if (this.matchIndexesSource.value.length) {
      this.setMatches(this.matchIndexesSource.value.slice());
    }
  }
}
