import { ChangeDetectionStrategy, ChangeDetectorRef, Component, EventEmitter, Input, OnInit, Output } from '@angular/core';
import { CommonModule } from '@angular/common';
import { IconComponent } from "../../../icon/icon.component";
import { ContactselectComponent } from "../../../contactselect/contactselect.component";
import { ButtonComponent } from "../../../button/button.component";
import { AvatarComponent } from "../../../avatar/avatar.component";
import { NgSelectModule } from '@ng-select/ng-select';
import { DatepickerComponent } from "../../../datepicker/datepicker.component";
import { FormsModule } from '@angular/forms';
import { CommonService } from '../../../../services/common/common.service';
import { filterItemType, QFACT_DATE_TYPE } from '../../../../interfaces/mark-nav-filter.interface';
import { selectedContactList } from '../../../../../marking/interfaces/fact.interface';
import { ContactService } from '../../../../services/contact/contact.service';
import { BaseNavFilterComponent } from '../../base/base-nav-filter.component';
import { TranslateModule } from '@ngx-translate/core';

@Component({
  selector: 'qfactdetailfilter',
  standalone: true,
  imports: [
    IconComponent,
    CommonModule,
    ContactselectComponent,
    ButtonComponent,
    AvatarComponent,
    NgSelectModule,
    DatepickerComponent,
    FormsModule,
    TranslateModule
  ],
  templateUrl: './qfactdetailfilter.component.html',
  styleUrl: './qfactdetailfilter.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class QfactdetailfilterComponent extends BaseNavFilterComponent implements OnInit {

  @Input() createDate: { start: string, end: string } | null = null;
  @Output() createDateChange = new EventEmitter<{ start: string, end: string } | null>();

  @Input() createBy: string[] = [];
  @Output() createByChange = new EventEmitter<string[]>();

  @Output() onEmitData = new EventEmitter<void>();

  @Input() cType: 'QF' | 'QM' = 'QF';

  selectedContact: selectedContactList[] = [];
  contactList: selectedContactList[] = [];

  selecteddatetype: number = 1;

  qfactdatetype = QFACT_DATE_TYPE;

  constructor(
    protected override cdr: ChangeDetectorRef,
    private readonly common: CommonService,
    private readonly contactService: ContactService
  ) {
    super(cdr);
  }

  ngOnInit(): void {
    if (this.cType === 'QF') {
      this.initData();
    }
  }

  async initData() {
    try {
      this.contactList = await this.contactService.getContactList(this.nCaseid);
      this.markForCheck();
    } catch (error) {
      console.error('Error initializing Qfact details', error);
    }
  }

  onActiveContactsChange(user: selectedContactList) {
    const idx = this.selectedContact.findIndex(selected => selected.nContactid === user.nContactid);
    if (idx === -1) {
      this.selectedContact.push(user);
      this.emitData();
    }
  }

  handleDateChange(e: any) {
    if (this.selecteddatetype == 1) {
      this.createDate = { start: e, end: e };
    } else {
      const [start, end] = e;
      if (!start || !end) {
        return;
      }
      this.createDate = { start: start, end: end };
    }

    this.emitData();
  }

  onRemoveContact(user: selectedContactList) {
    const idx = this.selectedContact.findIndex(selected => selected.nContactid === user.nContactid);
    if (idx !== -1) {
      this.selectedContact.splice(idx, 1);
      this.emitData();
    }
  }

  removeFilter(flag: string) {
    // Explicitly cast if needed or ensure template passes valid type.
    this.selectedContact = [];
    this.createDate = null;
    const index = this.selectedFilters.indexOf(flag as filterItemType);
    if (index > -1) {
      this.selectedFilters.splice(index, 1);
    }
    this.emitData();
    // Inherited onClear could be used if parent listens to it, but removeFilter logic here seems sufficient for internal clean up + emit.
  }

  emitData(): void {
    this.createBy = this.selectedContact.map(selected => selected.nContactid);
    this.createByChange.emit(this.createBy);
    this.createDateChange.emit(this.createDate);
    this.onEmitData.emit();
    this.markForCheck();
  }

  trackByIndex(index: number): number {
    return index;
  }
}
