import { ChangeDetectorRef, Component, EventEmitter, Input, Output, ViewChild } from '@angular/core';
import { IssueCreateComponent } from '../issue-create/issue-create.component';
import { IssueListComponent } from '../issue-list/issue-list.component';
import { IssueHeaderComponent } from "../issue-header/issue-header.component";
import { HeaderEventsType, HeaderType, issueManagerEvents, selectedIssues, userIssuePermission, } from '../../../interfaces/issue.interface';
import { SecureStorageService } from '../../../../core/services/storage/secure-storage.service';
import { hightlightModeType } from '../../../interfaces/feed.interface';
import { NavSearchBoxComponent } from '../../mark-nav/nav-components/nav-search-box/nav-search-box.component';
import { TranslateModule } from '@ngx-translate/core';
import { SelectionActionsService } from '../../../../shared/services/selection-actions/selection-actions.service';
import { IssueService } from '../../../services/issue/issue.service';
import { ButtonComponent } from '../../../../shared/components/button/button.component';
import { IconComponent } from '../../../../shared/components/icon/icon.component';

@Component({
  selector: 'issue-manage',
  standalone: true,
  imports: [IssueListComponent, IssueHeaderComponent, IssueCreateComponent, NavSearchBoxComponent, TranslateModule, ButtonComponent, IconComponent],
  templateUrl: './issue-manage.component.html',
  styleUrl: './issue-manage.component.scss'
})
export class IssueManageComponent {

  enableDelete: boolean = false;
  @Input() isCompoent: boolean = false;
  @Input() hightlightMode: string;
  createModeunable: boolean = false;
  @Output() OutEvent = new EventEmitter<any>();

  headerType: HeaderType; // M for Manage, C for Create

  enabledEdit: boolean = false;

  enableSearch: boolean = false;

  /** Toolbar QFact mode. When on, issue-list shows a checkbox per issue and
   *  pre-ticks them from each issue's `bQFactVisible` (with first-2-per-claim
   *  default). User ticks/unticks/drags freely; nothing hits the network until
   *  this flag flips back to false (or `close()` runs), at which point
   *  `flushQFactPrefs()` POSTs the diff to /issue/qfact/sequence. */
  enableQFact: boolean = false;

  @ViewChild(IssueListComponent) issueList?: IssueListComponent;

  @Input() nEditIssueid: string;
  @Output() nEditIssueidChange: EventEmitter<string> = new EventEmitter<string>();

  selectedIssues: selectedIssues[] = [];

  @Input() nUserid: string;
  @Input() nCaseid: string;

  @Input() visibleIssueModel: boolean;
  @Input() visibleIssueModelChange: EventEmitter<boolean>;

  /** Auto-enable QFact mode on first init. Set by callers that arrive via
   *  the QFact panel's Manage button (replaces the old standalone dialog).
   *  Only consumed once on ngOnInit — later changes are ignored so the
   *  user can freely toggle QFact mode from the header thereafter. */
  @Input() initialQFactMode: boolean = false;


  @Output() issueManagerEmit: EventEmitter<issueManagerEvents> = new EventEmitter<issueManagerEvents>();

  userIssuePermission: userIssuePermission = null;

  issuesLength: number = 0;


  constructor(
    private selectionActions: SelectionActionsService,
    private issueService: IssueService,
  ) { }

  issueFormDilog: any;

  async onEnableQFactChange(value: boolean) {
    const previous = this.enableQFact;
    this.enableQFact = value;
    if (value) {
      // Pre-tick from each issue's bQFactVisible (with first-2-per-claim
      // default for null) and snapshot the state for diffing on flush.
      // The ViewChild may not be ready yet on first frame — defer to the
      // next microtask so issue-list has wired up.
      Promise.resolve().then(() => this.issueList?.enterQFactMode());
    } else if (previous) {
      // Mode just turned off — flush any staged QFact changes.
      await this.flushQFactPrefs();
    }
  }

  /** POST the user's QFact-mode tick/drag/claim-reorder changes as a
   *  batched dialog-close flush, then notify the LEFT QFact panel to
   *  re-fetch. Splits issue and claim diffs into the two dedicated
   *  endpoints — Fact's APIs are never touched in QFact mode. No-op when
   *  nothing changed since the snapshot, so closing without QFact edits
   *  costs zero requests. */
  private async flushQFactPrefs(): Promise<void> {
    const list = this.issueList;
    if (!list) return;

    const issueChanges = list.getQFactChanges();
    const claimChanges = list.getQFactClaimChanges();
    if (!issueChanges.length && !claimChanges.length) return;

    // Fire both in parallel — they're independent and the LEFT panel
    // re-fetches once after both settle.
    const requests: Promise<boolean>[] = [];
    if (issueChanges.length) {
      requests.push(
        this.issueService.qfactSecquence(this.nUserid, {
          nCaseid: this.nCaseid,
          jIssues: issueChanges,
        }),
      );
    }
    if (claimChanges.length) {
      requests.push(
        this.issueService.qfactClaimSecquence(this.nUserid, {
          nCaseid: this.nCaseid,
          jClaims: claimChanges,
        }),
      );
    }
    const results = await Promise.all(requests);
    if (results.every(Boolean)) {
      list.commitQFactSnapshot();
      this.selectionActions.requestQFactRefresh();
    }
  }


  async ngOnInit() {
    if (this.nEditIssueid) {
      this.headerType = 'E';
    } else {
      this.headerType = 'M';
    }

    // Auto-enable QFact mode when this panel was opened from the QFact
    // panel's Manage button. Defer one microtask so the issue-list
    // ViewChild is wired up by the time enterQFactMode() runs.
    if (this.initialQFactMode) {
      Promise.resolve().then(() => this.onEnableQFactChange(true));
    }
  }

  async close() {
    try {
      // Persist any pending QFact mode edits before tearing the dialog down.
      // Fire-and-forget would race the LEFT panel's refresh subscription, so
      // we await — close() is invoked from a click handler that's fine to
      // be async.
      if (this.enableQFact) {
        await this.flushQFactPrefs();
      }
      if (this.nEditIssueid) {
        this.nEditIssueid = null;
        this.nEditIssueidChange.emit(this.nEditIssueid);
      }
      this.visibleIssueModel = false;
      this.visibleIssueModelChange?.emit(this.visibleIssueModel);
      this.issueManagerEmit.emit({ event: 'CLOSE', data: null });
    } catch (error) {
      console.log('error', error);
    }
  }

  headerEvents(event: { event: HeaderEventsType, data: any }) {
    if (event.event === 'close') {
      this.close();
    }
  }

  /** Save callout button (QFact mode only). Persists staged tick/drag
   *  changes without closing the dialog so the user can keep iterating.
   *  Same flush the close path uses — commits the snapshot and triggers
   *  the LEFT QFact panel to re-fetch via SelectionActionsService. */
  async save() {
    await this.flushQFactPrefs();
  }


  issuesLengthChange(event: number) {
    this.issuesLength = event;
    if (!this.issuesLength && this.hightlightMode && !this.createModeunable) {
      this.headerType = 'C';
      this.createModeunable = true;
    } else if (!this.issuesLength && this.hightlightMode && this.createModeunable) {
      this.close();
    }
  }
}

