import { Directive, ElementRef, HostListener, Input, OnInit, OnDestroy, Renderer2 } from '@angular/core';

@Directive({
  selector: '[appFadeScroll]',
  standalone: true
})
export class FadeScrollDirective implements OnInit, OnDestroy {
  @Input() fadeColor: string = '#1e3a8a'; // Default dark blue color
  @Input() fadeHeight: string = '56px'; // Default height (14 * 4 = 56px for h-14)
  @Input() zIndex: string = '20'; // Default z-index
  @Input() dynamicHeight: string | null = null; // User can pass custom height

  private topFadeElement: HTMLElement | null = null;
  private bottomFadeElement: HTMLElement | null = null;
  private scrollContainer: HTMLElement | null = null;

  constructor(
    private el: ElementRef,
    private renderer: Renderer2
  ) {}

  ngOnInit() {
    this.createFadeElements();
    this.updateFadeVisibility();
  }

  ngOnDestroy() {
    this.removeFadeElements();
  }

  private createFadeElements() {
    this.scrollContainer = this.el.nativeElement;
    
    // Create top fade element
    this.topFadeElement = this.renderer.createElement('div');
    this.renderer.addClass(this.topFadeElement, 'fade-scroll-top');
    this.renderer.setStyle(this.topFadeElement, 'position', 'sticky');
    this.renderer.setStyle(this.topFadeElement, 'top', '0');
    this.renderer.setStyle(this.topFadeElement, 'left', '0');
    this.renderer.setStyle(this.topFadeElement, 'right', '0');
    this.renderer.setStyle(this.topFadeElement, 'height', this.fadeHeight);
    this.renderer.setStyle(this.topFadeElement, 'z-index', this.zIndex);
    this.renderer.setStyle(this.topFadeElement, 'pointer-events', 'none');
    this.renderer.setStyle(this.topFadeElement, 'background', `linear-gradient(to bottom, ${this.fadeColor}, transparent)`);
    this.renderer.setStyle(this.topFadeElement, 'display', 'block');
    this.renderer.setStyle(this.topFadeElement, 'margin-top', `-${this.fadeHeight}`);

    // Create bottom fade element
    this.bottomFadeElement = this.renderer.createElement('div');
    this.renderer.addClass(this.bottomFadeElement, 'fade-scroll-bottom');
    this.renderer.setStyle(this.bottomFadeElement, 'position', 'sticky');
    this.renderer.setStyle(this.bottomFadeElement, 'bottom', '0');
    this.renderer.setStyle(this.bottomFadeElement, 'left', '0');
    this.renderer.setStyle(this.bottomFadeElement, 'right', '0');
    this.renderer.setStyle(this.bottomFadeElement, 'height', this.fadeHeight);
    this.renderer.setStyle(this.bottomFadeElement, 'z-index', this.zIndex);
    this.renderer.setStyle(this.bottomFadeElement, 'pointer-events', 'none');
    this.renderer.setStyle(this.bottomFadeElement, 'background', `linear-gradient(to top, ${this.fadeColor}, transparent)`);
    this.renderer.setStyle(this.bottomFadeElement, 'display', 'block');
    this.renderer.setStyle(this.bottomFadeElement, 'margin-bottom', `-${this.fadeHeight}`);

    // Insert top fade at the very beginning of content
    this.renderer.insertBefore(this.scrollContainer, this.topFadeElement, this.scrollContainer.firstChild);
    // Insert bottom fade at the end
    this.renderer.appendChild(this.scrollContainer, this.bottomFadeElement);

    // Ensure the scroll container has relative positioning
    this.renderer.setStyle(this.scrollContainer, 'position', 'relative');
  }

  @HostListener('scroll', ['$event'])
  onScroll(event: Event) {
    this.updateFadeVisibility();
  }

  private updateFadeVisibility() {
    if (!this.scrollContainer || !this.topFadeElement || !this.bottomFadeElement) {
      return;
    }

    const scrollTop = this.scrollContainer.scrollTop;
    const scrollHeight = this.scrollContainer.scrollHeight;
    const clientHeight = this.scrollContainer.clientHeight;
    const scrollBottom = scrollHeight - clientHeight - scrollTop;

    // Completely hide top fade when at start, show when scrolled down
    if (scrollTop <= 5) {
      this.renderer.setStyle(this.topFadeElement, 'display', 'none');
    } else {
      this.renderer.setStyle(this.topFadeElement, 'display', 'block');
    }

    // Completely hide bottom fade when at end, show when there's more content
    if (scrollBottom <= 5) {
      this.renderer.setStyle(this.bottomFadeElement, 'display', 'none');
    } else {
      this.renderer.setStyle(this.bottomFadeElement, 'display', 'block');
    }
  }

  private removeFadeElements() {
    if (this.topFadeElement) {
      this.renderer.removeChild(this.scrollContainer, this.topFadeElement);
      this.topFadeElement = null;
    }
    if (this.bottomFadeElement) {
      this.renderer.removeChild(this.scrollContainer, this.bottomFadeElement);
      this.bottomFadeElement = null;
    }
  }
}
