import { Component, EventEmitter, Input, OnInit, Output } from '@angular/core';
import { CommonModule } from '@angular/common';
import { TranslateModule } from '@ngx-translate/core';
import { ButtonComponent } from '../../button/button.component';
import { IconComponent } from '../../icon/icon.component';
import { MatMenuModule } from '@angular/material/menu';
import { NgSelectModule } from '@ng-select/ng-select';
import { FormsModule } from '@angular/forms';
import { MatCheckboxModule } from '@angular/material/checkbox';
import { DatepickerComponent } from '../../datepicker/datepicker.component';
import { ContactselectComponent } from '../../contactselect/contactselect.component';
import { filterItemType, QFACT_DATE_TYPE } from '../../../interfaces/mark-nav-filter.interface';
import { myTeamUsers } from '../../../../marking/interfaces/teamshare.interface';
import { ContactService } from '../../../services/contact/contact.service';
import { selectedContactList } from '../../../../marking/interfaces/fact.interface';
import { AvatarComponent } from "../../avatar/avatar.component";

@Component({
  selector: 'linkfilter',
  standalone: true,
  imports: [CommonModule, TranslateModule, ButtonComponent, IconComponent, MatMenuModule, NgSelectModule, FormsModule, MatCheckboxModule, DatepickerComponent, ContactselectComponent, AvatarComponent],
  templateUrl: './linkfilter.component.html',
  styleUrl: './linkfilter.component.scss'
})
export class LinkfilterComponent {

  @Input() nCaseid: string;
  @Input() nUserid: string;

  @Input() tab: string = 'A';
  @Input() tabmode: string = 'AL';
  @Input() isAll: boolean = false;

  resetSelect: any;

  qfactdatetype = QFACT_DATE_TYPE;

  userList: selectedContactList[] = [];

  selectedContact: selectedContactList[] = [];

  @Input() selectedFilters: filterItemType[];
  clearselect: any = null;
  selecteddatetype: any = 1;

  @Input() createDate: { start: string, end: string };
  @Output() createDateChange: EventEmitter<{ start: string, end: string }> = new EventEmitter<{ start: string, end: string }>();


  @Output() onEmitData: EventEmitter<any> = new EventEmitter<any>();

  constructor(private readonly contactSerice: ContactService) { }

  addfilter(x) {
    this.selectedFilters.push(x.value);
  }

  ngOnInit(): void {
    this.initData();
  }

  async initData() {
    this.userList = await this.contactSerice.getContactList(this.nCaseid);
    // this.userList = this.userList.filter(user => user.nContactid != this.nContactid);
  }


  handleDateChange(e: any) {

    if (this.selecteddatetype == 1) {
      this.createDate = { start: e, end: e };
    } else {
      const [start, end] = e;
      if (!start || !end) {
        return;
      }
      this.createDate = { start: start, end: end };
    }

    this.emitData();
  }

  onRemoveContact(user: selectedContactList) {
    const idx = this.selectedContact.findIndex(selected => selected.nContactid === user.nContactid);
    if (idx != -1) {
      this.selectedContact.splice(idx, 1);
      this.emitData();
    }
  }

  removeFilter(flag: filterItemType) {
    const index = this.selectedFilters.indexOf(flag);
    if (index > -1) {
      this.selectedFilters.splice(index, 1);
    }
    this.emitData();
  }

  onActiveContactsChange(user: selectedContactList) {
    const idx = this.selectedContact.findIndex(selected => selected.nContactid === user.nContactid);
    if (idx == -1) {
      this.selectedContact.push(user);
      this.emitData();
    }

  }

  trackByIndex(index: number): number {
    return index;
  }

  emitData() {
    // this.createBy = this.selectedContact.map(selected => selected.nContactid);
    // this.createByChange.emit(this.createBy);
    // this.createDateChange.emit(this.createDate);
    // this.onEmitData.emit();
  }

}
