import { Component, Input, ViewChild, ElementRef, AfterViewChecked, ChangeDetectorRef } from '@angular/core';
import { AvatarComponent } from "../../../../shared/components/avatar/avatar.component";
import { FormsModule } from '@angular/forms';
import { UserCommentComponent } from "../user-comment/user-comment.component";
import { AddCommentComponent } from "../add-comment/add-comment.component";
import { CommentService } from '../../../services/comment/comment.service';
import { CommentItem, CommentUserItem } from '../../../interfaces/comment.interface';
import { SocketService } from '../../../../core/services/socket/socket.service';
import { Subscription } from 'rxjs';


@Component({
  selector: 'fact-discuss',
  standalone: true,
  imports: [AvatarComponent, FormsModule, UserCommentComponent, AddCommentComponent],
  templateUrl: './fact-discuss.component.html',
  styleUrl: './fact-discuss.component.scss'
})
export class FactDiscussComponent implements AfterViewChecked {

  @Input() enableAddComment: boolean;

  @Input() nFSid: string;
  @Input() nSesid: string;
  @Input() nUserid: string;

  @ViewChild('commentsContainer', { static: false }) commentsContainer: ElementRef;

  isLoading: boolean = true;

  comments: CommentItem[] = [];

  commentsUsers: CommentUserItem[] = [];

  editCommentItem: CommentItem;

  socketSubscription: Subscription;

  @Input() nBundledetailid: string;

  shouldScrollToBottom = false;

  constructor(private commentService: CommentService, private socket: SocketService, private cdr: ChangeDetectorRef) { }

  async ngOnInit() {

    if (!this.nFSid) return;
    this.socket.joinFactComment(this.nFSid, this.nUserid);

    this.socketSubscription = this.socket.factCommentMessage().subscribe(res => {
      console.warn(res);
      if (res.nFSid != this.nFSid) return;
      if (res.type == 'FACT-MESSAGE') {
        const permission = res.permission;
        if (permission == 'N') {
          const ind = this.comments.findIndex(a => a.nCid == res.nCid);
          if (ind == -1) {
            this.comments.push(res);
            this.shouldScrollToBottom = true; // Mark that we need to scroll
          }
        } else if (permission == 'E') {
          const obj = this.comments.find(a => a.nCid == res.nCid);
          if (!obj) {
            this.comments.push(res);
            this.shouldScrollToBottom = true; // Mark that we need to scroll
          }
          else
            obj.cMsg = res.cMsg;
        } else if (permission == 'D') {
          const ind = this.comments.findIndex(a => a.nCid == res.nCid);
          if (ind > -1)
            this.comments.splice(ind, 1);
        }
      }
    })


    this.comments = await this.commentService.getComments(this.nFSid);
    this.commentsUsers = await this.commentService.getCommentsUsers(this.nFSid);

    this.isLoading = false;
    this.cdr.detectChanges();
  }

  ngAfterViewChecked() {
    if (this.shouldScrollToBottom) {
      this.scrollToBottom();
      this.shouldScrollToBottom = false;
    }
  }

  private scrollToBottom(): void {
    if (this.commentsContainer) {
      const element = this.commentsContainer.nativeElement;
      element.scrollTop = element.scrollHeight;
    }
  }

  removeComment(event: CommentItem) {
    const index = this.comments.findIndex(comment => comment.nCid === event.nCid);
    if (index !== -1) {
      this.comments.splice(index, 1);
    }
  }

  ngOnDestroy(): void {
    this.socket.leaveFactComment(this.nFSid, this.nUserid);
    if (this.socketSubscription)
      this.socketSubscription.unsubscribe()

  }
}