import { Component, EventEmitter, Input, Output } from '@angular/core';
import { hightlightModeType } from '../../../../rt/interfaces/feed.interface';
import { ButtonComponent } from "../../../../shared/components/button/button.component";
import { IconComponent } from "../../../../shared/components/icon/icon.component";
import { factAssigneeType, selectedContactList, selectedTaskItem } from '../../../interfaces/fact.interface';
import { MatRadioModule } from '@angular/material/radio';
import { FormsModule, ReactiveFormsModule } from '@angular/forms';
import { MatSelectModule } from '@angular/material/select';
import { NgSelectModule } from '@ng-select/ng-select';
import { AssignContactComponent } from "../assign-contact/assign-contact.component";
import { AssignFactTaskComponent } from "../assign-fact-task/assign-fact-task.component";
import { TeamshareComponent } from "../teamshare/teamshare.component";
import { CommonService } from '../../../../shared/services/common/common.service';
import { codeData } from '../../../../shared/interfaces/common.interface';
import { DocInfo, myTeamUsers } from '../../../../pdf/interfaces/pdf.interface';
import { MatDialog } from '@angular/material/dialog';
// Lazy-loaded inside addFactlink() to break an ES-module cycle with feed-display.
import type { FileexplorerComponent } from '../../../../shared/components/myfiles/fileexplorer/fileexplorer.component';
import { SourceCardComponent } from "../../../../shared/components/source-card/source-card.component";
import { DateFormComponent, jDateType } from '../date-form/date-form.component';

@Component({
  selector: 'full-fact',
  standalone: true,
  imports: [ButtonComponent, IconComponent, MatRadioModule, FormsModule, MatSelectModule, NgSelectModule, AssignContactComponent, AssignFactTaskComponent,
    TeamshareComponent, ReactiveFormsModule, SourceCardComponent, DateFormComponent],
  templateUrl: './full-fact.component.html',
  styleUrl: './full-fact.component.scss'
})
export class FullFactComponent {


  @Input() nCaseid: string;

  @Input() hightlightMode: hightlightModeType
  @Input() currentStep: number

  @Input() assignMode: factAssigneeType
  @Output() assignModeChange: EventEmitter<factAssigneeType> = new EventEmitter<factAssigneeType>()


  @Input() selectedContacts: selectedContactList[] = [];


  @Input() selectedTasks: selectedTaskItem[] = [];
  @Input() isSubmitted: boolean = false;


  datetype: any = 1;
  selectedDate: string = '';
  selectedM: any;
  selectedY: any;
  ToselectedM: any;
  ToselectedY: any;
  selcteddatetype: any = '1';
  
 @Input() showError: boolean = false;
  // dateList: { nValue: string, cKey: string }[] = [
  //   { nValue: '1', cKey: 'On' },
  //   { nValue: '2', cKey: 'Circa' },
  //   { nValue: '3', cKey: 'Before' },
  //   { nValue: '4', cKey: 'After' },
  //   { nValue: '5', cKey: 'Between' }
  // ];
  months: { nValue: string, cKey: string }[] = [
    { nValue: '1', cKey: '1' },
    { nValue: '2', cKey: '2' },
    { nValue: '3', cKey: '3' },
    { nValue: '4', cKey: '4' },
    { nValue: '5', cKey: '5' },
    { nValue: '6', cKey: '6' },
    { nValue: '7', cKey: '7' },
    { nValue: '8', cKey: '8' },
    { nValue: '9', cKey: '9' },
    { nValue: '10', cKey: '10' },
    { nValue: '11', cKey: '11' },
    { nValue: '12', cKey: '12' },
  ];

  years: { nValue: string, cKey: string }[] = [
    // Add years for the last 10 years dynamically
    ...Array.from({ length: 10 }, (_, i) => {
      const year = new Date().getFullYear() - i;
      return { nValue: year.toString(), cKey: year.toString() };
    }),
  ];


  filetypeList: codeData[] = [];
  statusList: codeData[] = [];
  @Input() userList: myTeamUsers[];
  dialogRef: any;

  @Input() jFiles: DocInfo[] = [];
  @Output() jFilesChange: EventEmitter<DocInfo[]> = new EventEmitter<DocInfo[]>

  @Input() frm: any;

  @Input() jDate: jDateType;
  @Output() jDateChange: EventEmitter<jDateType> = new EventEmitter<jDateType>();
  constructor(private common: CommonService,
    private dialog: MatDialog,
  ) { }

  ngOnInit() {
    this.initData();
  }

  async initData() {
    this.statusList = await this.common.getCode(24);
    this.filetypeList = await this.common.getCode(23);
  }

  handleAssignMode(cType: factAssigneeType) {
    this.assignMode = cType
    this.assignModeChange.emit(this.assignMode);
  }

  onDateChange(ev) {
    this.selectedDate = ev;
    console.log(ev);
  }

  async addFactlink() {
    if (this.dialogRef) return;
    // Lazy-load FileexplorerComponent to avoid ES module cycle at import time.
    const { FileexplorerComponent: FileexplorerCmp } = await import(
      '../../../../shared/components/myfiles/fileexplorer/fileexplorer.component'
    );
    this.dialogRef = this.dialog.open(FileexplorerCmp, {
      width: '90vw',
      height: '89vh',
      panelClass: ['rounded-xl', 'overflow-hidden'] // Rounded corners
      // data: {nCaseid:this.nCaseid}
    });
    this.dialogRef.componentInstance.nCaseid = this.nCaseid;
    this.dialogRef.componentInstance.isChooser = true;
    this.dialogRef.componentInstance.isIndividual = true;
    this.dialogRef.componentInstance.isLink = 'F';
    this.dialogRef.componentInstance.disabledFiles = this.jFiles.map(a => a.nBundledetailid);
    this.dialogRef.afterClosed().subscribe(result => {
      try {
        const files = this.dialogRef.componentInstance.choosedFile;
        this.jFiles = [...this.jFiles, ...files];
        this.jFilesChange.emit(this.jFiles);
      } catch (error) {
      }
      this.dialogRef = null;
    });
  }


  OnFilesEvnets(e: any, i: number) {

    if (e.type == 'D') {
      this.jFiles.splice(i, 1);
    }

  }


  OnDateChange(e: jDateType) {
    this.jDateChange.emit(this.jDate);
  }
}
