import { Component, EventEmitter, Input, Output, SimpleChanges } from '@angular/core';
import { ButtonComponent } from "../../../../shared/components/button/button.component";
import { FormsModule } from '@angular/forms';
import { CommentService } from '../../../services/comment/comment.service';
import { commentBuilderMdl, CommentBuilderRes, CommentItem, CommentUserItem } from '../../../interfaces/comment.interface';
import { UserService } from '../../../../adminpanel/services/user/user.service';
import { SecureStorageService } from '../../../../core/services/storage/secure-storage.service';
import { setUserInfo } from '../../../../core/interfaces/login.interface';

@Component({
  selector: 'add-comment',
  standalone: true,
  imports: [ButtonComponent, FormsModule],
  templateUrl: './add-comment.component.html',
  styleUrl: './add-comment.component.scss'
})
export class AddCommentComponent {


  @Input() nFSid: string;
  @Input() nSesid: string;
  @Input() nUserid: string;
  @Input() comments: CommentItem[];
  @Input() commentsUsers: CommentUserItem[];
  @Input() editCommentItem: CommentItem;
  @Output() editCommentItemChange = new EventEmitter<CommentItem>();


  userDetails: setUserInfo
  isLoading: boolean = false;

  @Input() nBundledetailid: string;

  @Input() shouldScrollToBottom: boolean;
  @Output() shouldScrollToBottomChange = new EventEmitter<boolean>(); // Add this line

  constructor(private commentService: CommentService, private store: SecureStorageService) { }

  currentComment = '';

  ngOnInit() {
    this.getUserDetails();
  }


  ngOnChanges(changes: SimpleChanges) {

    if (changes['editCommentItem'] && !changes['editCommentItem'].firstChange) {
      if (this.editCommentItem) {
        this.currentComment = this.editCommentItem.cMsg || '';
      }
    }
  }

  async getUserDetails() {
    this.userDetails = await this.store.getUserInfo();
  }


  async handleComment() {

    if (!this.currentComment.trim()) return;
    this.isLoading = true;
    const commentData: commentBuilderMdl = {
      cMsg: this.currentComment.trim(),
      nFSid: this.nFSid,
      nSesid: this.nSesid,
      nBundledetailid: this.nBundledetailid,
    }
    if (this.editCommentItem?.nCid) {
      commentData.nCid = this.editCommentItem.nCid;
      const res = await this.commentService.commentEdit(commentData);
      this.isLoading = false;
      if (res.msg == 1) {
        this.addComment(commentData.cMsg, this.editCommentItem.nCid, null, res.dUpdateDt);
        this.editCommentItem = null;
        this.editCommentItemChange.emit(this.editCommentItem);
      }
    }
    else {
      const res = await this.commentService.commentAdd(commentData);
      this.isLoading = false;
      if (res.msg == 1) {
        this.addComment(commentData.cMsg, res.nCid, res.dCreateDt);
      }
    }
  }


  async addComment(cMsg: string, nCid: string, dCreateDt?: string, dUpdateDt?: string) {
    this.currentComment = '';
    const newComment = {
      cMsg: cMsg,
      dCreateDt: dCreateDt || this.editCommentItem?.dCreateDt,
      dUpdateDt: dUpdateDt || this.editCommentItem?.dUpdateDt,
      nCid: nCid,
      nUserid: this.nUserid,
      cFname: this.userDetails?.cFname,
      cLname: this.userDetails?.cLname,
      cProfile: this.userDetails?.cProfile,
      todate: dCreateDt || this.editCommentItem?.todate,
    };
    this.comments.push(newComment);

    const idx = this.commentsUsers.findIndex(x => x.nUserid === this.nUserid);
    if (idx == -1) {
      this.commentsUsers.push({
        cFname: this.userDetails?.cFname,
        cLname: this.userDetails?.cLname,
        cProfile: this.userDetails?.cProfile,
        nUserid: this.nUserid
      });
    }
    this.shouldScrollToBottom = true;
    this.shouldScrollToBottomChange.emit(this.shouldScrollToBottom);
  }

  clearBox() {
    if (this.editCommentItem?.nCid) {

      const commentData: commentBuilderMdl = {
        cMsg: this.editCommentItem.cMsg,
        nFSid: this.nFSid,
        nSesid: this.nSesid,
        nBundledetailid: this.nBundledetailid,
      }
      this.addComment(commentData.cMsg, this.editCommentItem.nCid);
      this.editCommentItem = null;
      this.editCommentItemChange.emit(this.editCommentItem);
    }
    this.currentComment = '';
  }

}
