import { HttpClient, HttpErrorResponse, HttpParams } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { TostbarService } from '../../../core/services/tost/tostbar.service';
import { firstValueFrom } from 'rxjs';
import { environment } from '../../../../environments/environment';
import { commentBuilderMdl, CommentBuilderRes, CommentItem, CommentUserItem } from '../../interfaces/comment.interface';

@Injectable({
  providedIn: 'root'
})
export class CommentService {


  constructor(private http: HttpClient, private tost: TostbarService) { }



  async commentAdd(comment: commentBuilderMdl): Promise<CommentBuilderRes> {
    try {

      const res = await firstValueFrom(
        this.http.post<CommentBuilderRes>(
          `${environment.cloudUrl}${environment.coreservice}/comments/add`, comment
        )
      );

      if (res.msg != 1) {
        return { msg: -1, error: res.error };
      }

      return res;
    } catch (error: any) {
      console.error('error', error);
      if (error instanceof HttpErrorResponse) {
        return {
          msg: -1,
          error: error.error?.value || error.message,
        };
      }
      return { msg: -1, error: error.message };
    }
  }

  async commentEdit(comment: commentBuilderMdl): Promise<CommentBuilderRes> {
    try {

      const res = await firstValueFrom(
        this.http.put<CommentBuilderRes>(`${environment.cloudUrl}${environment.coreservice}/comments/edit`, comment)
      );

      if (res.msg != 1) {
        this.tost.error(res.value);
        return { msg: -1, error: res.value };
      }

      return res;

    } catch (error: any) {
      console.error(error);
      if (error instanceof HttpErrorResponse) {
        return {
          msg: -1,
          error: error.error?.value || error.message,
        };
      }
      return { msg: -1, error: error.message };
    }
  }


  async getComments(nFSid: string): Promise<any> {
    try {
      let params = new HttpParams().set('nFSid', nFSid)

      const res = await firstValueFrom(
        this.http.get<any>(
          `${environment.cloudUrl}${environment.coreservice}/comments/grid`, { params: params }
        )
      );

      return res;
    } catch (error) {
      console.error(error);
      return [];
    }
  }


  async getCommentsUsers(nFSid: string): Promise<CommentUserItem[]> {
    try {
      let params = new HttpParams().set('nFSid', nFSid)

      const res = await firstValueFrom(
        this.http.get<CommentUserItem[]>(
          `${environment.cloudUrl}${environment.coreservice}/comments/users`, { params: params }
        )
      );

      return res;
    } catch (error) {
      console.error(error);
      return [];
    }
  }

}
