import { ChangeDetectorRef, Component, Input, SimpleChanges } from '@angular/core';
import { IconComponent } from '../../../../../shared/components/icon/icon.component';
import { ButtonComponent } from '../../../../../shared/components/button/button.component';
import { AvatarComponent } from '../../../../../shared/components/avatar/avatar.component';
import { BadgeComponent } from '../../../../../shared/components/badge/badge.component';
import { MatMenuModule } from '@angular/material/menu';
import { ContactService } from '../../../../../shared/services/contact/contact.service';
import { ContactDetail } from '../../../../../shared/interfaces/issue.interface';

import { CommonModule } from '@angular/common';
import { TranslateModule } from '@ngx-translate/core';

@Component({
  selector: 'nav-contactview',
  standalone: true,
  imports: [CommonModule, TranslateModule, IconComponent, ButtonComponent, AvatarComponent, BadgeComponent, MatMenuModule],
  templateUrl: './nav-contactview.component.html',
  styleUrl: './nav-contactview.component.scss'
})
export class NavContactviewComponent {

  @Input() onlydetail: boolean = false;
  @Input() nContactid: string;

  @Input() detail: ContactDetail;

  constructor(private contactService: ContactService, private cdr: ChangeDetectorRef) { }




  ngOnInit(): void {

    this.initializeData();
  }


  ngOnChanges(changes: SimpleChanges): void {
    if (changes['detail']) {
      this.initializeData();
    }
  }

  private initializeData(): void {
    if (!this.nContactid) return;
    this.getContactDetail();

  }


  async getContactDetail() {
    this.detail = await this.contactService.getContactDetail(this.nContactid);
    this.cdr.detectChanges();
  }


  close() { }
  edit() { }

  deleteContact() { }

  viewfacts() { }

}
