import { MatDialog, MatDialogRef } from '@angular/material/dialog';
// Type-only import + dynamic runtime import breaks the ES-module cycle:
//   FileexplorerComponent → FeedDisplayComponent → SideModalManagerComponent
//   → DocLinkCreationComponent → FileexplorerComponent.
// `import type` is erased at compile time; the runtime reference loads lazily inside opendoclink().
import type { FileexplorerComponent } from '../../../../shared/components/myfiles/fileexplorer/fileexplorer.component';
import { SourceCardComponent } from "../../../../shared/components/source-card/source-card.component";
import { IconComponent } from "../../../../shared/components/icon/icon.component";
import { ButtonComponent } from "../../../../shared/components/button/button.component";
import { TeamshareComponent } from "../../fact/teamshare/teamshare.component";
import { MatFormFieldModule } from '@angular/material/form-field';
import { FactNoteComponent } from "../../../../pdf/components/facts/fact-note/fact-note.component";
