@Component({
  selector: 'doc-link-creation',
  standalone: true,
  imports: [SourceCardComponent, IconComponent, ButtonComponent, TeamshareComponent, MatFormFieldModule, FactNoteComponent],
  templateUrl: './doc-link-creation.component.html',
  styleUrl: './doc-link-creation.component.scss'
})
export class DocLinkCreationComponent {

  @Input() cFFrom: FACTFROM = 'RT';
  @Input() nBundledetailid: string;

  @Input() hightlightMode: hightlightModeType;
  @Input() hightlightModeChange: EventEmitter<hightlightModeType>;

  @Input() nCaseid: string;

  @Input() nSesid: string;
  @Input() nUserid: string;



  LinkdialogRef: MatDialogRef<FileexplorerComponent> | null = null;


  @Input() annotGlobMode: globAnnot = 'S';
  @Input() selectedlinktype: linkType = {} as linkType;

  jFiles: any[] = [];

  jTexts: string[] = [''];


  isEmpty: boolean = true;

  haschange: boolean = false;

  isNoteEdited: boolean = false;

  cPermission: 'N' | 'E' = 'N'

  userList: myTeamUsers[];

  isSubmitted: boolean = false;

  selectedContacts: selectedContactList[] = []


  constructor(private dialog: MatDialog, private common: CommonService, private tost: TostbarService, private annotsService: AnnotsService, private rtDoc: RtDocsService,
    private fds: FeedDisplayService, private cdr: ChangeDetectorRef, private broadCastService: BroadcastingService
  ) { }



  ngOnInit() {
    this.opendoclink();
    this.getMyTeamUsers()
  }

  async getMyTeamUsers() {
    this.userList = await this.common.getMyTeamUsers(this.nCaseid);
    if (this.userList?.length) {
      this.userList = this.userList.filter(x => x.nUserid != this.nUserid);
      // if (this.cPermission != 'E') {
        this.userList = this.userList.map(x => {
          if (x.isAdmin) {
            x.isSelected = true;
            x.bCanEdit = true;
            x.bCanCopy = true;
            x.bCanReshare = true;
            x.bCanComment = true;
          }
          return x;
        });

      // }
    }
  }

  async opendoclink() {
    if (this.LinkdialogRef) {
      this.LinkdialogRef.close();
    };
    // Lazy-load FileexplorerComponent to avoid an ES module cycle at import time.
    const { FileexplorerComponent: FileexplorerCmp } = await import(
      '../../../../shared/components/myfiles/fileexplorer/fileexplorer.component'
    );
    this.LinkdialogRef = this.dialog.open(FileexplorerCmp, {
      width: '90vw',
      height: '89vh',
      panelClass: ['rounded-xl', 'overflow-hidden'],
      disableClose: false
      // data: {nCaseid:this.nCaseid}
    });
    this.LinkdialogRef.componentInstance.nCaseid = this.nCaseid;
    this.LinkdialogRef.componentInstance.isChooser = true;
    this.LinkdialogRef.componentInstance.isIndividual = true;
    this.LinkdialogRef.componentInstance.isLink = 'D';
    this.LinkdialogRef.componentInstance.disabledFiles = this.jFiles.map(a => a.nBundledetailid);
    this.LinkdialogRef.afterClosed().subscribe(result => {
      console.log('result', result);

      try {
        const files = this.LinkdialogRef.componentInstance.choosedFile;
        this.jFiles = [...this.jFiles, ...files];
        if (this.jFiles.length == 0) {
          this.closeDocLinkCreation();
        }
      } catch (error) {
      }

      console.log('files', this.jFiles);
      this.cdr.detectChanges();
    });
  }

  addmore() {
    this.opendoclink();
  }

  back() {
    this.annotsService.removeTemp();
    this.closeDocLinkCreation();

  }

  OnFilesEvnets(ev: any, index: number) {
    if (ev.type == 'D') {
      this.jFiles.splice(index, 1);
    }
  }



  textchange(ev) {
    this.haschange = true;
  }


  emitFactNote(event) {
    if (event.event == 'ADD-CONTECT') {
      // this.selectedContacts.push(event.data.original)
    }
  }


  convToStr(val: any) {
    return JSON.stringify(val);
  }



  choosenfiles() {
    return this.jFiles.map((a) => ([a.nBundledetailid, a.jLinktype, ((a.highlights && a.highlights.length) ? a.highlights : []), (a.texts ? a.texts : [])]))
  }

  // getJCordinates() {
  //   try {
  //     const annotation: feedAnnotations[] = this.annotsService.getTemp() || [];

  //     if (!annotation.length && this.cPermission == 'N') {
  //       this.tost.error('Please mark the annotation first');
  //       return { msg: -1, data: [] };
  //     }

  //     const firstAnnot = annotation[0] || null;

  //     const jCordinates: feedAnnotCordinates[] = this.cPermission === 'N' ? firstAnnot?.jCordinates || [] : [];
  //     const nPage = this.cPermission === 'N' ? firstAnnot?.nPage || 0 : 0;//this.docDetail?.nPage
  //     const nLine = this.cPermission === 'N' ? firstAnnot?.nLine || 0 : 0; //this.docDetail?.nLine
  //     return { msg: 1, data: jCordinates, nLine, nPage };

  //   } catch (error) {
  //     return { msg: -1, data: [], nLine: 0, nPage: 0 };
  //   }

  // }


  getJCordinates(cFFrom: any) {
    debugger;
    try {
      const annotation: feedAnnotations[] = this.annotsService.getTemp() || [];

      if (!annotation.length && this.cPermission == 'N') {
        this.tost.error('Please mark the annotation first');
        this.isSubmitted = false;
        return { msg: -1, data: [] };
      }

      const firstAnnot = annotation[0] || null;
      let jCordinates: any;
      if (cFFrom == 'RT') {
        const jCordinat: feedAnnotCordinates[] = this.cPermission === 'N' ? firstAnnot?.jCordinates || [] : [];
        jCordinates = jCordinat;
      } else {
        // Normalize annotation fields for the backend DTO:
        //   - rects: always an array. Pen annotations have no rects
        //     (lines instead); without the default the field would
        //     drop out via JSON.stringify and the DTO rejects with
        //     "rects must be an array".
        //   - lines: always numbers. Pen savePoint stores coords via
        //     `.toFixed(2)`, which returns a STRING; the DTO rejects
        //     with "each value in lines must be a number". Coerce
        //     here so a pen drawing can save as a doclink without
        //     touching the upstream pen-capture path.
        const rawLines = firstAnnot?.['lines'] ?? [];
        const numericLines = rawLines.map((line: any) => Array.isArray(line)
          ? line.map((coord: any) => typeof coord === 'string' ? parseFloat(coord) : coord)
          : line);
        const factCordinate: factAnnotCordinates = {
          uuid: firstAnnot?.['uuid'],
          type: firstAnnot?.['type'],
          page: firstAnnot?.['page'],
          rects: firstAnnot?.['rects'] ?? [],
          lines: numericLines,
          width: firstAnnot?.['width']
        };

        const jFactCordinat: any[] = this.cPermission === 'N' ? firstAnnot ? [factCordinate] : [] : [];
        jCordinates = jFactCordinat;
      }

      const nPage = this.cPermission === 'N' ? firstAnnot?.nPage || firstAnnot?.['page'] || 0 : 0;//this.docDetail?.nPage
      const nLine = this.cPermission === 'N' ? firstAnnot?.nLine || 0 : 0; //this.docDetail?.nLine
      return { msg: 1, data: jCordinates, nLine, nPage };

    } catch (error) {
      return { msg: -1, data: [], nLine: 0, nPage: 0 };
    }

  }



  async submit() {

    try {

      if (!this.jFiles.length) return;
      if (this.isSubmitted) {
        return;
      }
      this.isSubmitted = true;
      const { msg, data: jCordinates, nLine, nPage } = this.annotGlobMode != 'M' ? this.getJCordinates(this.cFFrom) : { msg: 1, data: [], nLine: 0, nPage: 0 };
      if (msg == -1) {
        return;
      }

      let mdl: any = {
        // jLT: this.convToStr(this.selectedlinktype),
        // jAn: this.convToStr(this.tempAnnots.map(a => a.annots)),
        jT: this.convToStr(this.jTexts.filter(a => a)),
        jDl: this.convToStr(this.choosenfiles()),
        jOT: this.convToStr(this.getJOText()),
        jUsers: this.convToStr(this.choosenUsers()),
        // jContacts: this.convToStr(this.selectedContacts.map(a => a.nContactid)),
        cType: 'S',
        cDFrom: this.cFFrom,
        nCaseid: this.nCaseid,
        nLine, nPage
      }
      if (this.annotGlobMode == 'M') {
        mdl.jLT = this.convToStr(this.selectedlinktype);
        mdl.cType = this.annotGlobMode;
      }

      if (this.cFFrom == 'RT') {
        mdl.nSesid = this.nSesid;
        mdl.jCordinates = jCordinates;
      } else {
        mdl.nBundledetailid = this.nBundledetailid;
        mdl.jAn = jCordinates;
      }

      const res = await this.rtDoc.saveDoc(mdl);
      this.isSubmitted = false;
      if (res["msg"] == 1) {
        this.updateAnnots(res.nDocid, 'D', jCordinates, nLine, nPage);
        this.tost.openSnackBar(res["value"]);
        this.fds.emit('DOC-ADDED', { nDocid: res.nDocid });
        this.closeDocLinkCreation();

        // Send reload event
        this.sendReloadEvent('doc-link-created', { nDocid: res.nDocid });
      } else {
        this.tost.error('doc creation failed');
      }
    } catch (error) {
      this.isSubmitted = false;
      this.tost.error('Doc link creation failed');
    }

  }

  updateAnnots(id: string, cType: annotTypes, jCordinates: feedAnnotCordinates[], nLine: number, nPage: number) {
    const updateAnnot = { jCordinates, id: id, nLine, nPage, cType };
    this.annotsService.set(updateAnnot);
    this.annotsService.removeTemp();
  }


  choosenUsers() {
    return this.userList.filter(f => f.isSelected).map(m => ({
      nUserid: m.nUserid,
      bCanEdit: m.bCanEdit,
      bCanCopy: m.bCanCopy,
      bCanReshare: m.bCanReshare,
      bCanComment: m.bCanComment
    }));
  }


  closeDocLinkCreation() {
    this.hightlightMode = null;
    this.hightlightModeChange.emit(this.hightlightMode);
    this.fds.emit('CLOSE', {});
  }



  getJOText(): string[] {
    const tempAnnots = this.annotsService.getTemp();
    if (tempAnnots.length) {
      const fullText = tempAnnots[0].fullText || '';
      return [fullText];
    }
    return [];
  }

  // Add this method
  private sendReloadEvent(action: string, data: any) {
    console.log('Sending reload event:', { action, data, nCaseid: this.nCaseid });
    this.broadCastService.portMessage({
      event: BROADCAST_EVENTS.RELOAD_FILE_LIST,
      data: {
        nCaseid: this.nCaseid,
        action: action,
        ...data,
        timestamp: Date.now(),
        tabId: this.broadCastService.tabId
      }
    });
  }
}
