import { ChangeDetectorRef, Component, EventEmitter, Input, OnInit, Output } from '@angular/core';
import { IconComponent } from "../../../../shared/components/icon/icon.component";
import { ColorpickerComponent } from '../../../../shared/components/colorpicker2/colorpicker/colorpicker.component';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatChipsModule } from '@angular/material/chips';
import { MatAutocompleteModule, MatAutocompleteSelectedEvent } from '@angular/material/autocomplete';
import { FormBuilder, FormControl, FormGroup, FormsModule, ReactiveFormsModule, Validators } from '@angular/forms';
import { ButtonComponent } from '../../../../shared/components/button/button.component';
import { MatMenuModule } from '@angular/material/menu';
import { IssueService } from '../../../services/issue/issue.service';
import { CommonfunctionService } from '../../../../core/utility/commonfunction.service';
import { TostbarService } from '../../../../core/services/tost/tostbar.service';
import { MatDialogRef } from '@angular/material/dialog';
import { HeaderType, issueListRes, userIssuePermission } from '../../../interfaces/issue.interface';
import { TranslateModule, TranslateService } from '@ngx-translate/core';


@Component({
  selector: 'issue-create',
  standalone: true,
  imports: [ColorpickerComponent, IconComponent, MatFormFieldModule, MatChipsModule, MatAutocompleteModule, ReactiveFormsModule, FormsModule, ButtonComponent, MatMenuModule, TranslateModule],
  templateUrl: './issue-create.component.html',
  styleUrl: './issue-create.component.scss'
})
export class IssueCreateComponent implements OnInit {

  cClr: string = '#ff9163';
  colorslist = [
    { cClr: '#ff8f63' },
  ];
  selecteditem: any = '';
  tempitem: any;
  isLoading: boolean = false;

  issue_frm: FormGroup = new FormGroup({});

  categories: any = [];
  tempCat: any = [];
  isLoaded: boolean = true;
  previousIssue: any;
  isCentered: boolean = false;

  isSubmitting: boolean = false;
  isDeleting: boolean = false;

  @Input() nUserid: string = null;
  @Input() nCaseid: string = null;

  @Input() headerType: HeaderType = 'M'; // M for Manage, C for Create
  @Output() headerTypeChange: EventEmitter<HeaderType> = new EventEmitter<HeaderType>();

  @Input() nEditIssueid: string = null;
  @Output() nEditIssueidChange: EventEmitter<string> = new EventEmitter<string>();

  issueData: issueListRes = null;

  @Input() userIssuePermission: userIssuePermission;
  @Output() userIssuePermissionChange: EventEmitter<userIssuePermission> = new EventEmitter<userIssuePermission>();


  constructor(private formBuilder: FormBuilder, public issueService: IssueService,
    private cs: CommonfunctionService,
    private tost: TostbarService,
    private cdr: ChangeDetectorRef,
    private translate: TranslateService
  ) {


  }


  async ngOnInit() {

    this.initiliseForm();
    this.getCategory();
    if (this.nEditIssueid && this.headerType == 'E') {
      await this.fetchIssueByid();
      this.patchIssueForm();
    }


    this.previousIssue = this.cClr;
    this.isLoaded = false;

    this.cdr.detectChanges();
  }

  initiliseForm() {
    this.issue_frm = this.formBuilder.group({
      nIid: [0],
      cIName: ['', [Validators.required]],
      cCategory: new FormControl(''),
      nICid: new FormControl(''),
      permission: ['N'],
      cColor: [''],
    });
  }


  async getCategory() {
    let cat = await this.issueService.getCategory(this.nCaseid, this.nUserid);
    this.categories = cat;
    this.tempCat = this.categories;
  }


  close() {

    if (this.nEditIssueid) {
      this.nEditIssueid = null;
      this.nEditIssueidChange.emit(this.nEditIssueid);
    }

    this.headerType = 'M';
    this.headerTypeChange.emit(this.headerType);
  }

  add(event: any): void {

    const value = event.value;
    if (value) {
      this.selecteditem = value;
    }
  }


  tempadd(ev) {
    this.tempitem = ev.target.value;
  }


  filterOptions(event) {
    let filterValue = event.target.value.toLowerCase();
    if (filterValue) {
      this.tempCat = this.categories.filter(category => category.cCategory.toLowerCase().includes(filterValue));
    } else {
      this.tempCat = this.categories;
    }
  }



  async selected(event: MatAutocompleteSelectedEvent): Promise<void> {
    console.log('event.option.value', event.option.value);


    if (event.option.value?.cCategory) {
      this.selecteditem = event.option.value.cCategory;
      this.issue_frm.patchValue({
        nICid: event.option.value.nICid
      })
    } else {
      this.selecteditem = event.option.value;
    }

    if (!this.selecteditem) {
      this.selecteditem = '';
      return;
    }
    this.tempitem = '';
    if (!this.categories.filter(e => e.cCategory == this.selecteditem).length) {
      let mdl = {
        nICid: null,
        nCaseid: this.nCaseid,
        cCategory: this.selecteditem,
        dCreateDt: this.cs.getCurrentTime(),
        nUserid: this.nUserid
      }
      const res = await this.issueService.categoryCreation(mdl);
      this.isLoading = false;
      if (res[0]["msg"] == 1) {
        this.categories.push({
          cCategory: this.selecteditem,
          nICid: res[0]["nICid"]
        });
        this.issue_frm.patchValue({
          nICid: res[0]["nICid"]
        })
      }
    }
    setTimeout(() => {
      this.tempCat = this.categories;
    });
  }


  checktemp() {
    try {
      return this.categories.filter(e => e.cCategory == this.tempitem).length ? true : false;
    } catch (error) {
      return false;
    }
  }



  removeHash(colorCode: string): string {
    if (colorCode.startsWith('#')) {
      return colorCode.substring(1); // Remove the '#' character
    }
    return colorCode; // Return the original color code if it doesn't contain '#'
  }

  async submitForm() {


    this.isLoading = true;
    if (this.issue_frm.invalid) {
      this.isLoading = false;
      return;
    }
    let x = this.issue_frm.value;
    let nIDcatid = x.nICid;
    if (!nIDcatid) {
      let dts = this.categories.filter(e => e.cICtype == 'U');
      if (dts.length) {
        nIDcatid = dts[0].nICid
      } else {
        if (this.categories.find(a => a.cCategory == 'Unassigned')) {
          nIDcatid = this.categories.find(a => a.cCategory == 'Unassigned').nICid;
        } else {
          this.tost.openSnackBar(this.translate.instant('rt.issueCreate.pleaseCreateCategory'), 'E');
          return;
        }
      }
    }

    this.cClr = this.removeHash(this.cClr);

    let mdl = {
      nIid: x.nIid,
      cIName: x.cIName,
      cColor: this.cClr !== 'ff8f63' ? this.cClr : (x.cColor ? x.cColor : 'ff8f63'),
      nICid: nIDcatid,
      nCaseid: this.nCaseid,
    }

    this.isSubmitting = true;
    mdl['nUserid'] = this.nUserid;
    let res: boolean = false;
    if (x.permission == 'N') {
      mdl['dCreatedt'] = this.cs.getCurrentTime();
      mdl['nIid'] = 0;
      res = await this.issueService.issueCreation(mdl);
    } else {
      mdl['dUpdatedt'] = this.cs.getCurrentTime();
      res = await this.issueService.issueUpdate(mdl)
    }

    this.isSubmitting = false;
    this.isLoading = false;

    if (res) {
      this.headerType = 'M';
      this.headerTypeChange.emit(this.headerType);
    }
    this.cdr.detectChanges();
  }


  async deleteIssue() {

    if (!this.nEditIssueid) return;
    this.isDeleting = true;
    const res = await this.issueService.issueDelete(this.nEditIssueid);
    this.isDeleting = false;

    if (res) {
      this.headerType = 'M';
      this.headerTypeChange.emit(this.headerType);
      this.nEditIssueid = null;
      this.nEditIssueidChange.emit(this.nEditIssueid);
    }
  }


  async fetchIssueByid() {

    const params = {
      nCaseid: this.nCaseid,
      nUserid: this.nUserid,
      nIid: this.nEditIssueid,
      nSessionid: null
    }
    const res = await this.issueService.fetchIssueByid(params);

    if (res && res.length) {
      this.issueData = res[0];
    }
  }

  patchIssueForm() {
    if (!this.issueData) {
      console.error('issuedata not found');
      return;
    }

    this.issue_frm.patchValue({
      nIid: this.issueData.nIid,
      cIName: this.issueData.cIName,
      nICid: this.issueData.nICid,
      cColor: this.issueData.cColor,
      permission: 'E',
    })

    this.cClr = '#' + this.issueData.cColor;
    this.selecteditem = this.issueData.cCategory; //this.data.value.cCategory == 'Unassigned' ? '' :


  }

  cancel() {
    this.close();
  }

  validate(): boolean {
    const nICid = this.issue_frm.get('nICid')?.value;
    const cCategory = this.issue_frm.get('cCategory')?.value;

    // Case: both empty → allow
    if (!nICid && !cCategory) {
      return true;
    }

    if (nICid) {
      console.log(this.categories.some(cat => cat.nICid === nICid))
      return this.categories.some(cat => cat.nICid === nICid);
    }

    return false;
  }

}
