import { ChangeDetectorRef, Component, EventEmitter, Input, Output, SimpleChanges } from '@angular/core';
import { markingDetailMode } from '../../../../interfaces/marknav.interface';
import { factdata } from '../../../../../shared/interfaces/fact.interface';
import { FactService } from '../../../../../shared/services/fact/fact.service';
import { NavSharePermissionComponent } from "../nav-share-permission/nav-share-permission.component";
import { EmptyComponent } from "../../../../../shared/components/empty/empty.component";
import { NavSelectedTasksComponent } from "../nav-selected-tasks/nav-selected-tasks.component";
import { AvatarComponent } from "../../../../../shared/components/avatar/avatar.component";
import { NavContactviewComponent } from "../nav-contactview/nav-contactview.component";
import { IconComponent } from "../../../../../shared/components/icon/icon.component";
import { selectedContactList, selectedTaskItem } from '../../../../../marking/interfaces/fact.interface';
import { selectedTaskList } from '../../../../../shared/interfaces/issue.interface';
import { myTeamUsers } from '../../../../../marking/interfaces/teamshare.interface';
import { CommonService } from '../../../../../shared/services/common/common.service';
import { RtFactService } from '../../../../../shared/services/rt-fact/rt-fact.service';
import { FactDiscussComponent } from "../../../../../userpanel/components/comment/fact-discuss/fact-discuss.component";
import { NgStyle, CommonModule } from '@angular/common';
import { QuickPreviewComponent } from "../../../../../userpanel/components/quick-preview/quick-preview.component";

import { TranslateModule } from '@ngx-translate/core';

@Component({
  selector: 'nav-fact-view-model',
  standalone: true,
  imports: [CommonModule, NavSharePermissionComponent, EmptyComponent, NavSelectedTasksComponent, AvatarComponent, NavContactviewComponent, IconComponent, FactDiscussComponent, NgStyle, QuickPreviewComponent, TranslateModule],
  templateUrl: './nav-fact-view-model.component.html',
  styleUrl: './nav-fact-view-model.component.scss'
})
export class NavFactViewModelComponent {

  @Input() isIndividual: boolean = false;
  @Input() detailViewMode: markingDetailMode;
  @Input() factData: factdata;
  @Input() nUserid: string;
  @Input() nCaseid: string;

  userList: myTeamUsers[] = [];

  selectedContacts: selectedContactList[] = [];
  selectedTasks: selectedTaskItem[] = [];

  @Input() selectedTab: string = 'L';

  @Input() isFullViewLoading: boolean = false;
  @Output() isFullViewLoadingChange: EventEmitter<boolean> = new EventEmitter<boolean>();

  @Output() closeEvent: EventEmitter<boolean> = new EventEmitter<boolean>();

  constructor(private rtFactService: RtFactService, private common: CommonService, private cdr: ChangeDetectorRef) { }

  ngOnInit() {
    this.handleFullViewDetails();
  }


  ngOnChanges(changes: SimpleChanges) {
    if (changes['factData'] || changes['detailViewMode']) {
      this.handleFullViewDetails();
    }
  }



  async handleFullViewDetails() {

    if (this.isFullViewLoading) {
      return
    }
    this.isFullViewLoading = true;
    this.isFullViewLoadingChange.emit(this.isFullViewLoading);
    if (this.detailViewMode == 'C') {
      this.selectedContacts = await this.rtFactService.getFactContact(this.factData?.nFSid);
    } else if (this.detailViewMode == 'T') {
      const res: any = await this.rtFactService.getFactTask(this.factData?.nFSid);
      this.selectedTasks = res[0] || [];
      this.selectedTasks.map(a => {
        let user = [];
        if (res[1]) {
          user = res[1].filter(b => b.jTaskid.includes(a.nTaskid));
        }
        a['teamlist'] = user ? user : [];
        const reminder = res[2].find((a: selectedTaskItem) => a.nTaskid == a.nTaskid);
        if (reminder) {
          a.dReminderDt = reminder.dReminderDt;
        }
      });

    } else if (this.detailViewMode == 'S') {
      this.userList = await this.common.getMyTeamUsers(this.nCaseid);
      const res = await this.rtFactService.getFactShare(this.factData?.nFSid);
      this.handleSharedUsers(this.userList, res);
    }
    this.isFullViewLoading = false;
    this.isFullViewLoadingChange.emit(this.isFullViewLoading);
    this.cdr.detectChanges();

  }

  handleSharedUsers(users: myTeamUsers[], factUsers: myTeamUsers[]) {
    if (!users?.length || !factUsers?.length) return;

    users.map(f => {
      const factUser = factUsers.find(m => m.nUserid == f.nUserid);
      if (factUser) {
        f.isSelected = true;
        f.bCanEdit = factUser.bCanEdit;
        f.bCanCopy = factUser.bCanCopy;
        f.bCanReshare = factUser.bCanReshare;
        f.bCanComment = factUser.bCanComment;
      }
    })

    this.cdr.detectChanges();

  }

  close() {
    this.isFullViewLoading = false;
    this.isFullViewLoadingChange.emit(this.isFullViewLoading);
    this.closeEvent.emit(true);
    this.cdr.detectChanges();
  }

  handleExpand(x: selectedContactList) {
    x.isExpanded = !x.isExpanded;
    this.cdr.detectChanges();
  }

}
