import { Component, EventEmitter, Input, Output } from '@angular/core';
import { AvatarComponent } from "../../../../shared/components/avatar/avatar.component";
import { FormsModule } from '@angular/forms';
import { CommentItem } from '../../../interfaces/comment.interface';
import { DatePipe } from '@angular/common';
import { CounterComponent } from '../../../../shared/components/counter/counter.component';
import { IconComponent } from "../../../../shared/components/icon/icon.component";

@Component({
  selector: 'user-comment',
  standalone: true,
  imports: [AvatarComponent, FormsModule, DatePipe, CounterComponent, IconComponent],
  templateUrl: './user-comment.component.html',
  styleUrl: './user-comment.component.scss'
})
export class UserCommentComponent {

  @Input() comment: CommentItem;
  @Input() isCurrentUser: boolean;

  isEditable: boolean = true;

  @Input() editCommentItem: CommentItem;
  @Output() editCommentItemChange = new EventEmitter<CommentItem>();


  @Input() commentLength: number;
  @Input() index: number;

  @Input() enableAddComment: boolean;

  editComment() {
    this.editCommentItem = this.comment;
    this.editCommentItemChange.emit(this.editCommentItem);
  }

}
