import { Component, EventEmitter, Input, Output } from '@angular/core';
import { IconComponent } from "../../../../../shared/components/icon/icon.component";
import { SourceCardComponent } from "../../../../../shared/components/source-card/source-card.component";
import { ButtonComponent } from "../../../../../shared/components/button/button.component";
import { DatePipe, CommonModule } from '@angular/common';
import { FACTFROM } from '../../../../../pdf/interfaces/pdf.interface';



import { TranslateModule } from '@ngx-translate/core';

@Component({
  selector: 'nav-doc-link-card',
  standalone: true,
  imports: [CommonModule, IconComponent, SourceCardComponent, ButtonComponent, DatePipe, TranslateModule],
  templateUrl: './nav-doc-link-card.component.html',
  styleUrl: './nav-doc-link-card.component.scss'
})
export class NavDocLinkCardComponent {

  @Input() cFFrom: FACTFROM = 'RT';

  @Input() x: any = {};
  @Input() userList: any = [];
  @Input() nCaseid: string;
  @Input() viewmode: string;
  @Output() OnView: EventEmitter<any> = new EventEmitter();
  @Output() onCardEvent: EventEmitter<any> = new EventEmitter();
  isActive: boolean = false;
  @Input() isAllLinks: boolean = false;

  selectedType: string;

  @Input() nUserid: string;
  @Input() nFSid: string;


  constructor() { }



  async ngOnInit() {
  }




  getDetail(type) {
    if (this.selectedType && this.nFSid) {
      this.selectedType = null;
    } else {
      this.selectedType = type;
    }
    this.onCardEvent.emit({ event: 'DOC-CARD-VIEW', type: type });
  }

  OnViewEvent(x) {
    this.OnView.emit(x);
  }
}
