import { HttpClient, HttpParams } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { environment } from '../../../../environments/environment';
import { myTeamUsers } from '../../../marking/interfaces/teamshare.interface';

@Injectable({
  providedIn: 'root'
})
export class RtDocsService {


  constructor(private http: HttpClient) { }

  async saveDoc(mdl): Promise<any> {
    try {
      let res: any;


      let apiAlias = `${environment.cloudUrl2}${environment.realtimeserive}`;     
      res = await firstValueFrom(
        this.http.post<any>(`${apiAlias}/doclink/insertdoc`, mdl)
      );
      if (res && res.msg == 1) {
        return res;
      } else {
        return res;
      }
    } catch (err) {
      return { msg: -1, error: err, value: '' };
    }
  }

  async deleteDoc(nDocid: string): Promise<any> {
    try {
      const res: any = await firstValueFrom(
        this.http.post<any>(`${environment.cloudUrl2}${environment.realtimeserive}/doclink/docdelete`, { nDocid: nDocid })
      );
      return res[0];
    } catch (err) {
      return { msg: -1, error: err, value: 'Failed to delete' };
    }
  }

  async getDocShare(nDocid: string): Promise<myTeamUsers[]> {
    const params = new HttpParams().set('nDocid', nDocid)
    try {
      const res = await firstValueFrom(
        this.http.get<myTeamUsers[]>(
          `${environment.cloudUrl2}${environment.realtimeserive}/doclink/docshared`, { params: params }
        )
      );
      return res || [];
    } catch (error) {
      console.error(error)
      return [];
    }
  }


}
