import { Component, EventEmitter, Input, Output, SimpleChanges } from '@angular/core';
import { MarknavService } from '../../../../services/marknav/marknav.service';
import { finalFilterList } from '../../../../../shared/interfaces/filter.interface';
import { IssueDetail, LinkDetail, markNavEvents, navigateModeType, sortByType, viewModeType } from '../../../../interfaces/marknav.interface';
import { FactcardComponent } from "../../../../../pdf/components/linkviews/facts/factcard/factcard.component";
import { myTeamUsers } from '../../../../../marking/interfaces/teamshare.interface';
import { Subject, Subscription } from 'rxjs';
import { feedAnnotCordinates } from '../../../../interfaces/annotation.interface';
import { FeedDisplayService } from '../../../../services/feed-display/feed-display.service';
import { FACTFROM } from '../../../../../pdf/interfaces/pdf.interface';
import { historyBuilderMdl, markNavjFilters } from '../../../../../shared/interfaces/mark-nav-filter.interface';
import { BroadcastingService } from '../../../../../core/services/broadcasting/broadcasting.service';
import { broadCastBody } from '../../../../../core/interfaces/login.interface';
import { annotDetails } from '../../../../interfaces/feed.interface';

import { CommonModule } from '@angular/common';
import { TranslateModule } from '@ngx-translate/core';

@Component({
  selector: 'navfact-chronology',
  standalone: true,
  imports: [CommonModule, TranslateModule, FactcardComponent,],
  templateUrl: './navfact-chronology.component.html',
  styleUrl: './navfact-chronology.component.scss'
})
export class NavfactChronologyComponent {


  @Input() cFFrom: FACTFROM = 'RT';
  @Input() nBundledetailid: string;
  @Input() nSesid: string;
  @Input() nUserid: string;

  @Input() sortBy: sortByType;
  @Input() viewmode: viewModeType;
  @Input() userList: myTeamUsers[] = [];
  @Input() selectedMode: navigateModeType;

  factlist: any = [];
  @Input() jFilters: markNavjFilters;
  @Input() noOfRecord: number;
  @Output() noOfRecordChange: EventEmitter<number> = new EventEmitter<number>();

  @Input() nFSid: string;
  type: string;



  @Output() OnEvent: EventEmitter<any> = new EventEmitter();

  @Input() historyEnabled: boolean;

  @Input() bIsTranscipt: boolean;

  factSheetDeleteSubscription: Subscription;

  @Input() visibleAnnotDetails: annotDetails;
  @Input() visibleAnnotDetailsChange: EventEmitter<annotDetails>;

  @Input() bisHistorExists: boolean;
  @Output() bisHistorExistsChange: EventEmitter<boolean> = new EventEmitter<boolean>();

  @Input() selectedIds: string[];
  @Output() selectedIdsChange: EventEmitter<string[]> = new EventEmitter<string[]>();

  constructor(private markNavService: MarknavService, private fds: FeedDisplayService, private broadCastService: BroadcastingService) {
    this.factSheetDeleteSubscription = this.broadCastService.factSheetDeleteListener().subscribe((body: broadCastBody) => {
      this.handleFactSheetDelete(body?.data);
    });
  }


  ngOnInit(): void {
    this.getFactList(1);
  }

  async getFactList(pageNo) {
    let res: any = await this.markNavService.getFactlist(this.nSesid, this.nUserid, 'H', this.sortBy, pageNo, this.jFilters, this.historyEnabled, this.bIsTranscipt, 'F', this.nBundledetailid) || [];

    this.factlist = res && res.length ? res[0] : [];

    this.noOfRecord = this.factlist.length;
    this.noOfRecordChange.emit(this.noOfRecord);
    let issueList: IssueDetail[] = res[1] || [];
    let linkList: LinkDetail[] = res[2] || [];
    try {
      this.factlist.forEach(element => {
        // const annotPages = element?.jCordinates?.map((x: feedAnnotCordinates) => x.p) || [];
        // const uniquePages = [...new Set(annotPages)];
        // element.cPageno = uniquePages[0] || 0;
        element.cPageno = element.nPage;
        element.issueList = issueList.filter(x => x.jFSids.includes(element.nFSid));
        element.linkfile = linkList.filter(x => x.nFSid == element.nFSid);
      })

      if (this.factlist?.length) {
        this.handleSequence(this.factlist, 'F');
      }
    } catch (error) {
    }
    this.selectedIds = this.factlist.map(i => i.nFSid);
    this.selectedIdsChange.emit(this.selectedIds);
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes && changes['sortBy'] && !changes['sortBy'].firstChange) {
      this.getFactList(1);
    }

    if (changes['jFilters'] && !changes['jFilters'].firstChange) {
      this.getFactList(1);
    }

    if (changes["historyEnabled"] && !changes["historyEnabled"].firstChange) {
      this.getFactList(1);
    }

    if (changes["nFSid"]) {
      if (changes["nFSid"].currentValue == null) {
        this.nFSid = null;
      }
    }
  }

  ngOnDestroy(): void {

    try {
      if (this.factSheetDeleteSubscription) {
        this.factSheetDeleteSubscription.unsubscribe();
      }
    } catch (error) {

    }
  }

  async getCardEvent(e: any, x, i: number) {
    if (this.type == e.data && this.nFSid == x.nFSid) {
      this.nFSid = null;
      this.type = '';
    } else {
      this.nFSid = x.nFSid;
      this.type = e.data;
    }

    if (e.event == 'VIEW') {
      e.x = x;
      this.OnEvent.next(e);
    }
  }

  OnViewEvent(x) {
    this.OnEvent.next({
      event: 'VIEW-DETAIL-LINKS',
      data: {
        id: x.nFSid,
        type: 'F'
      }
    });

    if (this.cFFrom == 'I') {
      this.scrollFeedToPage(x);
    }
  }

  handleSequence(list: any[], type: string) {
    let nSequence = 0;
    let nCurrentPage = 0;
    for (const item of list) {
      // if (item.cSource != type) continue;
      nSequence++;
      if ((item.nPage != nCurrentPage)) {
        nSequence = 1;
        nCurrentPage = item.nPage;
      }
      item.nSequence = nSequence;
    }
  }


  scrollFeedToPage(x: any) {
    if (x?.nPage) {
      this.fds.emit('SCROLL-TO-PAGE', { page: x.nPage, id: x.nFSid });
    } else if (x?.jLinktype?.pages) {
      this.fds.emit('SCROLL-TO-PAGE', { page: x?.jLinktype?.pages[0], id: x.nFSid });
    } else if (x?.jLinktype?.start) {
      this.fds.emit('SCROLL-TO-PAGE', { page: x?.jLinktype?.start, id: x.nFSid });
    } else {
      this.fds.emit('SCROLL-TO-PAGE', { page: 1, id: x.nFSid });
    }
  }

  async historyInsert(x: any) {
    const history: historyBuilderMdl = {
      nBundledetailid: this.nBundledetailid,
      nSesid: this.nSesid,
      nUserid: this.nUserid,
      cType: 'F',
      nFSid: x.nFSid
    };

    const res = await this.markNavService.historyInsert(history)
    if (res.msg == 1) {
      this.bisHistorExists = true;
      this.bisHistorExistsChange.emit(this.bisHistorExists);
    }
  }

  handleFactSheetDelete(data: { nFSid: string }) {
    if (!data?.nFSid) return;
    this.factlist = this.factlist.filter((x) => x.nFSid != data?.nFSid);
    this.noOfRecord = this.factlist.length;
    this.noOfRecordChange.emit(this.noOfRecord);
  }

  updateVisibleAnnotDetails(data: any) {
    try {
      const annotDetails: annotDetails = {
        id: data.nFSid,
        cType: 'F',
      };
      this.visibleAnnotDetails = annotDetails;
      this.visibleAnnotDetailsChange.emit(this.visibleAnnotDetails);
    } catch (error) {
      console.log('er', error);

    }
  }

}
