import { Component, EventEmitter, Input, Output } from '@angular/core';
import { ButtonComponent } from "../../../../../shared/components/button/button.component";
import { IconComponent } from "../../../../../shared/components/icon/icon.component";
import { SelectedIssuesComponent } from "../../../../../shared/components/issues/selected-issues/selected-issues.component";
import { DatePipe, CommonModule } from '@angular/common';
import { MatMenuModule } from '@angular/material/menu';
import { FactboxComponent } from "../../../../../pdf/components/facts/factbox/factbox.component";
import { FACTFROM } from '../../../../../pdf/interfaces/pdf.interface';
import { timestampPipe } from '../../../../pip/timestamp.pip';

import { TranslateModule } from '@ngx-translate/core';

@Component({
  selector: 'nav-qfactcard',
  standalone: true,
  imports: [CommonModule, ButtonComponent, IconComponent, SelectedIssuesComponent, DatePipe, MatMenuModule, FactboxComponent, timestampPipe, TranslateModule],
  templateUrl: './nav-qfactcard.component.html',
  styleUrl: './nav-qfactcard.component.scss'
})
export class NavQfactcardComponent {

  @Input() cFFrom: FACTFROM = 'RT';
  @Input() nBundledetailid: string;
  @Input() data: any;
  @Input() isQmark: boolean;
  @Input() activeID: string;
  @Input() type: string;
  /** The currently logged-in user's id. Used to gate the Convert /
   *  Edit / Delete action bar so non-owners can see the QFact in the
   *  marknav (they have read access via team sharing) but can't trigger
   *  mutations that the underlying SPs would silently no-op on
   *  (et_fact_insert / et_fact_delete / et_fact_update all gate writes
   *  on `FactMaster.nUserid = nMasterid`).
   *
   *  When unset (undefined / null), default behaviour is to SHOW the
   *  buttons — fail-open protects callers that haven't been updated to
   *  pass nUserid through yet. */
  @Input() nUserid?: string;
  @Output() OnView: EventEmitter<any> = new EventEmitter();
  @Output() CardEvent = new EventEmitter<any>();

  /** True when the viewer owns this QFact (or when ownership cannot be
   *  determined — fail-open to preserve existing behaviour for unknown
   *  callers). Drives action-bar visibility in the template. */
  get isOwner(): boolean {
    if (!this.nUserid) return true;       // fail-open: no viewer id passed
    if (!this.data?.nUserid) return true; // fail-open: data missing creator id
    return this.data.nUserid === this.nUserid;
  }

  ngOnInit() {
  }

  OnViewEvent(data) {
    this.OnView.emit(data);
  }

  handleFactCardClick(event: 'CONVERT-TO-FACT' | 'EDIT-Q-FACT' | 'DELETE-FACT') {
    if (!this.data?.nFSid) return;
    this.CardEvent.emit({ data: this.data, event });
  }
}