import { ChangeDetectionStrategy, ChangeDetectorRef, Component, EventEmitter, Input, Output } from '@angular/core';
import { filterItemType } from '../../../../interfaces/mark-nav-filter.interface';
import { IconComponent } from "../../../icon/icon.component";
import { MatCheckboxChange, MatCheckboxModule } from '@angular/material/checkbox';
import { BaseNavFilterComponent } from '../../base/base-nav-filter.component';
import { TranslateModule } from '@ngx-translate/core';

@Component({
  selector: 'share-filter',
  standalone: true,
  imports: [IconComponent, MatCheckboxModule, TranslateModule],
  templateUrl: './share-filter.component.html',
  styleUrl: './share-filter.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class ShareFilterComponent extends BaseNavFilterComponent {

  @Input() IsCreateByMe: boolean = false;
  @Output() IsCreateByMeChange = new EventEmitter<boolean>();

  @Input() IsShared: boolean = false;
  @Output() IsSharedChange = new EventEmitter<boolean>();

  @Output() onEmitData = new EventEmitter<void>();

  constructor(protected override cdr: ChangeDetectorRef) {
    super(cdr);
  }

  // Template calls removeall('S'), where 'S' is compatible with filterItemType?
  // Assuming 'S' is a valid filterItemType string literal.
  removeall(flag: string) { // flag is passed as 'S' from template
    const index = this.selectedFilters.indexOf(flag as filterItemType);
    if (index > -1) {
      this.selectedFilters.splice(index, 1);
    }
    this.IsCreateByMe = false;
    this.IsShared = false;
    this.emitData();
    this.onClear.emit();
  }

  handleChange(event: MatCheckboxChange, flag: 'M' | 'O') {
    if (flag === 'M') {
      this.IsCreateByMe = event.checked;
    }
    if (flag === 'O') {
      this.IsShared = event.checked;
    }
    this.emitData();
  }

  emitData(): void {
    this.IsCreateByMeChange.emit(this.IsCreateByMe);
    this.IsSharedChange.emit(this.IsShared);
    this.onEmitData.emit();
    this.markForCheck();
  }
}
