import { CdkDrag } from '@angular/cdk/drag-drop';
import { Component, EventEmitter, Input, Output } from '@angular/core';
import { IconComponent } from "../../../../../shared/components/icon/icon.component";
import { MatCheckboxModule } from '@angular/material/checkbox';
import { FormsModule } from '@angular/forms';
import { ButtonComponent } from "../../../../../shared/components/button/button.component";
import { SearchService } from '../../../../search/search.service';
import { FeedDisplayService } from '../../../../services/feed-display/feed-display.service';
import { SearchSharedService } from './nav-search-box.service';
import { CommonModule } from '@angular/common';
import { TranslateModule } from '@ngx-translate/core';

@Component({
  selector: 'app-nav-search-box',
  standalone: true,
  imports: [CommonModule, IconComponent, MatCheckboxModule, FormsModule, ButtonComponent, TranslateModule],
  templateUrl: './nav-search-box.component.html',
  styleUrl: './nav-search-box.component.scss'
})
export class NavSearchBoxComponent {
  searchTerm = '';
  wholeWord = false;

  totalMatches = 0;
  currentMatch = 0;

  constructor(private searchShared: SearchSharedService) { }

  ngOnInit() {
    this.searchShared.totalMatches$.subscribe(count => this.totalMatches = count);
    this.searchShared.currentMatch$.subscribe(idx => this.currentMatch = idx);
  }

  clearsearch() {
    this.searchTerm = '';
    this.searchShared.setSearchTerm('');
  }

  search() {
    this.searchShared.setSearchTerm(this.searchTerm);
    this.searchShared.setWholeWord(this.wholeWord);
  }

  onNext() {
    this.searchShared.nextMatch();
  }

  onPrevious() {
    this.searchShared.previousMatch();
  }
}

