// highlightIssue.pipe.ts
import { Pipe, PipeTransform } from '@angular/core';
import { DomSanitizer, SafeHtml } from '@angular/platform-browser';

@Pipe({ name: 'highlightIssue', standalone: true })
export class HighlightIssuePipe implements PipeTransform {
  constructor(private sanitizer: DomSanitizer) {}

  transform(
    text: string,
    search: string,
    wholeWord: boolean = false,
    activeIndex: number = -1   // 1..N within this card; -1 = none
  ): SafeHtml {
    if (!search || !text) return text;

    const escaped = search.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const pattern = wholeWord
      ? new RegExp(`\\b(${escaped})\\b`, 'gi')
      : new RegExp(escaped, 'gi');

    let i = 0;
    const html = text.replace(pattern, (m) => {
      i++;
      const isActive = (i === activeIndex);
      // use <mark> so you get good semantics; style with classes
      return `<mark class="hl ${isActive ? 'hl-active' : ''}" data-occ="${i}">${m}</mark>`;
    });

    // IMPORTANT: return SafeHtml to avoid Angular sanitization stripping styles/classes
    return this.sanitizer.bypassSecurityTrustHtml(html);
  }
}
