import { Component, EventEmitter, Input, Output } from '@angular/core';
import { MatMenuModule } from '@angular/material/menu';
import { MatTooltipModule } from '@angular/material/tooltip';
import { ButtonComponent } from "../../../../shared/components/button/button.component";
import { IconComponent } from "../../../../shared/components/icon/icon.component";
import { HeaderEventsType, HeaderType, selectedIssues } from '../../../interfaces/issue.interface';
import { IssueService } from '../../../services/issue/issue.service';
import { TranslateModule } from '@ngx-translate/core';

@Component({
  selector: 'issue-header',
  standalone: true,
  imports: [IconComponent, ButtonComponent, MatMenuModule, MatTooltipModule, TranslateModule],
  templateUrl: './issue-header.component.html',
  styleUrl: './issue-header.component.scss'
})

export class IssueHeaderComponent {

  @Input() headerType: HeaderType = 'M'; // M for Manage, C for Create
  @Output() headerTypeChange: EventEmitter<HeaderType> = new EventEmitter<HeaderType>();

  @Input() enableDelete: boolean = false;

  @Output() enableDeleteChange: EventEmitter<boolean> = new EventEmitter<boolean>();

  @Input() enabledEdit: boolean = false;
  @Output() enabledEditChange: EventEmitter<boolean> = new EventEmitter<boolean>();

  @Input() enableSearch: boolean = false;
  @Output() enableSearchChange: EventEmitter<boolean> = new EventEmitter<boolean>();

  @Input() enableQFact: boolean = false;
  @Output() enableQFactChange: EventEmitter<boolean> = new EventEmitter<boolean>();

  @Output() headerEvents: EventEmitter<{ event: HeaderEventsType, data: any }> = new EventEmitter<{ event: HeaderEventsType, data: any }>();


  @Input() selectedIssues: selectedIssues[] = [];
  @Output() selectedIssuesChange: EventEmitter<selectedIssues[]> = new EventEmitter<selectedIssues[]>();


  @Input() issuesLength: number = 0;

  enableinfo: boolean = false;

  constructor(private issueService: IssueService) { }

  handleDeleteButton() {
    if (this.enableDelete) {
      this.selectedIssues = [];
      this.selectedIssuesChange.emit(this.selectedIssues);
    }

    // When enabling delete, disable edit & qfact
    if (!this.enableDelete && this.enabledEdit) {
      this.enabledEdit = false;
      this.enabledEditChange.emit(this.enabledEdit);
    }
    if (!this.enableDelete && this.enableQFact) {
      this.enableQFact = false;
      this.enableQFactChange.emit(this.enableQFact);
    }

    this.enableDelete = !this.enableDelete;
    this.enableDeleteChange.emit(this.enableDelete);
  }


  handleEditButton() {
    if (this.enabledEdit) {
      this.selectedIssues = [];
      this.selectedIssuesChange.emit(this.selectedIssues);
    }

    // When enabling edit, disable delete & qfact
    if (!this.enabledEdit && this.enableDelete) {
      this.enableDelete = false;
      this.enableDeleteChange.emit(this.enableDelete);
    }
    if (!this.enabledEdit && this.enableQFact) {
      this.enableQFact = false;
      this.enableQFactChange.emit(this.enableQFact);
    }

    this.enabledEdit = !this.enabledEdit;
    this.enabledEditChange.emit(this.enabledEdit);
  }

  handleQFactButton() {
    // QFact mode is mutually exclusive with edit & delete — toggling it on
    // disables those, and toggling it off clears any selections accumulated
    // while it was active so we don't leak them into the next mode.
    if (this.enableQFact) {
      this.selectedIssues = [];
      this.selectedIssuesChange.emit(this.selectedIssues);
    }

    if (!this.enableQFact && this.enabledEdit) {
      this.enabledEdit = false;
      this.enabledEditChange.emit(this.enabledEdit);
    }
    if (!this.enableQFact && this.enableDelete) {
      this.enableDelete = false;
      this.enableDeleteChange.emit(this.enableDelete);
    }

    this.enableQFact = !this.enableQFact;
    this.enableQFactChange.emit(this.enableQFact);
  }

  handleShowSearchBox() {
    this.enableSearch = !this.enableSearch;
    this.enableSearchChange.emit(this.enableSearch)
  }


  openIssueForm() {

    if (this.enableDelete) {
      this.enableDelete = false;
      this.enableDeleteChange.emit(this.enableDelete);
    }
    this.headerType = 'C';
    this.headerTypeChange.emit(this.headerType);
  }

  close() {

    if (['C', 'E'].includes(this.headerType)) {
      this.headerType = 'M';
      this.headerTypeChange.emit(this.headerType);
    }
    else if (this.headerType == 'M') {
      this.headerType = null;
      this.headerEvents.emit({ event: 'close', data: null });
    }
  }

  async deleteIssues() {

    const jIids = this.selectedIssues.map(a => a.nIid);
    if (!jIids.length) return;
    const res = await this.issueService.deleteMultiIssue(jIids);

    if (res) {
      this.selectedIssues = [];
      this.selectedIssuesChange.emit(this.selectedIssues);
      this.enableDelete = false;
      this.enableDeleteChange.emit(this.enableDelete);
    }
  }



}
