  initLinkLines() {

    const elm = this.mainscroll.nativeElement
    this.scrollList({ target: elm } as any)

    // const hostEl = this.mainscroll.elementRef.nativeElement as HTMLElement;

  }

  async selecttab(x: { type: string }) {
    if (this.selectedTab === x.type) return;
    this.showfilter = false;

    // Save current tab's filters before switching
    this.filtersByTab[this.selectedTab] = this.jFilters ? { ...this.jFilters } : null;

    this.selectedTab = x.type;

    if (x.type === 'L') {
      this.selectedMode = 'AL';
    } else {
      const modeMap: { [key: string]: string } = {
        F: 'FCH',
        QF: 'QF',
        A: 'A',
        QM: 'QM',
      };
      this.selectedMode = modeMap[x.type] || 'A';
      this.getUserList();
    }

    // Restore or inherit filters for the new tab
    if (this.filtersByTab[x.type] !== undefined) {
      // Tab has been visited before — restore its saved filters
      this.jFilters = this.filtersByTab[x.type] ? { ...this.filtersByTab[x.type] } : null;
    } else {
      // First visit — inherit a clone of the 'A' tab's filters
      const allTabFilters = this.filtersByTab['A'];
      this.jFilters = allTabFilters ? { ...allTabFilters } : null;
      this.filtersByTab[x.type] = this.jFilters ? { ...this.jFilters } : null;
    }
    this.filterlength = this.jFilters && Object.keys(this.jFilters).length > 0 ? Object.keys(this.jFilters).length : 0;
    this.jFiltersChange.emit(this.jFilters);

    this.historyEnabled = false;
    this.factMode = null;
    this.docMode = null;
    this.visibleAnnotDetails = null;
    this.visibleAnnotDetailsChange.emit(this.visibleAnnotDetails);
    this.historyExist();
    this.initLinkLines();

  }

  selectSubtab(type: navigateModeType) {
    this.showfilter = false;
    this.selectedMode = type;
    this.historyEnabled = false;
    this.factMode = null;
    this.docMode = null;

    // const cType = this.jFilters.cType || null;
    // this.jFilters = null;
    // if (cType) this.jFilters = { ...this.jFilters, cType };
    this.historyExist();
  }


  onReachEnd() {
    this.reachedBottom = true;
    this.reachedTop = false;
    this.scrolled = true;
  }


  onScroll(flag) {
    // Set reachedTop/reachedBottom based on flag
    if (flag === 'T') {
      this.reachedTop = true;
      this.reachedBottom = false;
    } else if (flag === 'E') {
      this.reachedBottom = true;
      this.reachedTop = false;
    } else {
      this.reachedTop = false;
      this.reachedBottom = false;
    }

    this.scrolled = true;
  }

  onScroll2(flag, ev, mainscroll) {
    // Use scroll event to update all three variables
    const scrollTop = ev.target.scrollTop;
    const scrollHeight = ev.target.scrollHeight;
    const clientHeight = ev.target.clientHeight;
    this.scrolled = scrollTop > 0;
    this.reachedTop = scrollTop === 0;
    this.reachedBottom = scrollTop + clientHeight >= scrollHeight;
    this.checkTargetItemVisibility();

    // this.connectionService.clearConnections();
    // this.connectionService.updateConnectionsOnScroll('R', mainscroll);
  }


  openfilter() {
    if (this.showfilter && this.filterVisible && (!this.jFilters || Object.keys(this.jFilters).length === 0)) {
      this.showfilter = false;
      this.filterVisible = false;
    }
    else if (this.showfilter && !this.filterVisible) {
      this.filterVisible = true;
    } else if (this.showfilter && this.filterVisible) {
      this.filterVisible = false;
    } else if (!this.showfilter && this.filterVisible) {
      this.showfilter = true;
    }
    else if (!this.showfilter && !this.filterVisible) {
      this.showfilter = true;
      this.filterVisible = true;
      this.contactFilter = {
        ...(this.nBundledetailid && { nBundledetailid: this.nBundledetailid }),
        ...(this.nSesid && { nSesid: this.nSesid })
      };
      this.factMode = null;
      this.nFSid = null
    }
    this.cdr.detectChanges();
  }

  onIsAllQfChange(e) {
    this.isAllQf = e
  }

  // gotop(elm) {
  //   if (this.visibleAnnotDetails)
  //     this.visibleAnnotDetails = JSON.parse(JSON.stringify(this.visibleAnnotDetails));
  //   // elm.scrollTo({
  //   //   top: 0,
  //   //   behavior: 'smooth'
  //   // });
  // }

  gotop(elm) {
    if (this.visibleAnnotDetails?.id) {
      // Store the target item ID
      // this.targetItemId = this.visibleAnnotDetails.id;

      // Find the target element in the navall component
      const targetElement = document.querySelector(`[id="${this.visibleAnnotDetails.id}"]`);

      if (targetElement && elm) {
        // Scroll to the target element
        targetElement.scrollIntoView({
          behavior: 'smooth',
          block: 'center'
        });
      } else if (elm && elm.scrollTo) {
        // Fallback to scroll to top
        elm.scrollTo({
          top: 0,
          behavior: 'smooth'
        });
      }

      // Update scroll state variables
      this.scrolled = false;
      this.reachedTop = true;
      this.reachedBottom = false;
    }
  }

  async getCardEvent(e: markNavEvents) {
    if (e.event == 'EDIT-Q-FACT') {
      this.handleQfactState(e.data.nFSid, 'QF');
    }
    else if (e.event == 'CONVERT-TO-FACT') {
      this.handleQfactState(e.data.nFSid, 'F');
    }
    else if (e.event == 'VIEW') {
      this.OpenFullView(e.x, e.data);
    }
    else if (e.event == 'DOC-CARD-VIEW') {
      console.log('e', e);
      this.handleDocCardView(e.data, e.type as markingDetailMode);
    }
  }

  handleSort(type: 'asc' | 'desc') {
    this.sortBy = type;
  }

  private handleQfactState(nFSid: string, highlightMode: hightlightModeType): void {
    this.nEditFactid = nFSid;
    this.visibleMarkNavModel = false;
    this.hightlightMode = highlightMode;

    this.visibleMarkNavModelChange.emit(this.visibleMarkNavModel);
    this.hightlightModeChange.emit(this.hightlightMode);
    this.nEditFactidChange.emit(this.nEditFactid);
    this.cdr.detectChanges();
  }

